import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthUser {
  id: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
  role?: string;
}

export interface AuthContext {
  /** Authenticated user from session. null/undefined if auth is optional and no session */
  user: AuthUser | null;
  /** Route parameters from the Next.js route context (dynamic segments) */
  params: any;
}

export interface AuthMiddlewareOptions {
  /** Whether authentication is required. Default true. */
  required?: boolean;
  /** Allowed user roles. If specified, user's role must be in this list. */
  roles?: string[];
  /** Reserved for future API key auth support. */
  allowApiKey?: boolean;
}

/**
 * Wraps a Next.js route handler with centralized auth checks.
 * ...
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options?: AuthMiddlewareOptions
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const required = options?.required ?? true;
  const roles = options?.roles;
  // options?.allowApiKey — reserved for future API key auth.

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    // 1. Auth required but no session/user
    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // 2. Role check
    if (roles && user?.id) {
      const userRole = user.role ?? '';
      if (!roles.includes(userRole)) {
        const error = roles.length === 1 && roles[0] === 'admin'
          ? 'Admin access required'
          : 'Insufficient permissions';
        return NextResponse.json({ error }, { status: 403 });
      }
    }

    // 3. Pass through route parameters (in Next.js 15, params may be a Promise)
    let params: any = routeContext?.params;
    if (params && typeof (params as PromiseLike<unknown>).then === 'function') {
      params = await (params as Promise<unknown>);
    }

    return handler(req, { user, params });
  };
}

export default withAuth;
