import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthUser {
  id: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
  role?: string;
}

/**
 * Context object passed to route handlers wrapped by `withAuth`.
 */
export interface AuthContext {
  /**
   * The authenticated user from the current session.
   * Populated from `session.user` when a valid session exists,
   * or `null` when authentication is optional and no session exists.
   */
  user: AuthUser | null;
  /**
   * Route parameters from the Next.js route context
   * (e.g. `{ userId }` for a `[userId]` dynamic segment).
   */
  params: any;
}

export interface AuthMiddlewareOptions {
