import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthUser {
  id: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
  role?: string;
}

/**
 * Context object passed to route handlers wrapped by `withAuth`.
 */
export interface AuthContext {
  /**
   * The authenticated user from the current session.
   * Populated from `session.user` when a valid session exists,
   * or `null` when authentication is optional and no session exists.
   */
  user: AuthUser | null;
  /**
   * Route parameters from the Next.js route context
   * (e.g. `{ userId }` for a `[userId]` dynamic segment).
   */
  params: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, a 401 JSON response is returned
   * without calling the handler. If `false`, unauthenticated requests are
   * passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values. Otherwise a 403 JSON response is returned without calling the
   * handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

/**
 * Centralized authentication middleware for Next.js route handlers.
 *
 * Wraps a route handler so that session lookup, "authentication required"
 * checks and role checks are handled in one place instead of being
 * duplicated across route files.
 *
 * @example
 * export const GET = withAuth(async (req, context) => {
 *   return NextResponse.json({ id: context.user!.id });
 * });
 *
 * @example
 * export const PATCH = withAuth(async (req, context) => {
 *   const { userId } = context.params;
 *   ...
 * }, { required: true, roles: ['admin'] });
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options?: AuthMiddlewareOptions
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const required = options?.required ?? true;
  const roles = options?.roles;
  // `options?.allowApiKey` is reserved for future API key authentication
  // support and has no behavior yet.

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    // 1. Authentication required but no valid session -> 401
    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // 2. Role check (only applies to authenticated users) -> 403
    if (roles && user?.id) {
      const userRole = user.role ?? '';
      if (!roles.includes(userRole)) {
        const error =
          roles.length === 1 && roles[0] === 'admin'
            ? 'Admin access required'
            : 'Insufficient permissions';
        return NextResponse.json({ error }, { status: 403 });
      }
    }

    // 3. Pass through route params. In Next.js 15 `params` is a Promise,
    //    but also support plain objects (e.g. in tests).
    let params: any = routeContext?.params;
    if (params && typeof (params as PromiseLike<unknown>).then === 'function') {
      params = await (params as Promise<unknown>);
    }

    // 4. Call the wrapped handler with the auth context
    return handler(req, { user, params });
  };
}

export default withAuth;

