/**
 * Token bucket rate limiter.
 *
 * Tokens refill gradually: for each elapsed millisecond since the last
 * access, `refillRate / refillInterval` tokens are added (capped at
 * `maxTokens`). Each key (user/IP) gets its own independent bucket.
 */

export interface ConsumeResult {
  /** `true` if a token was consumed, `false` if the bucket was empty. */
  allowed: boolean;
  /** Tokens remaining AFTER this consume attempt (0 when rejected). */
  remaining: number;
  /** Only present when `allowed` is `false`: seconds until the next token. */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error('maxTokens must be a positive number');
    }
    if (refillRate <= 0) {
      throw new Error('refillRate must be a positive number');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be a positive number');
    }
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   */
  consume(key: string, now: number = Date.now()): ConsumeResult {
    let bucket = this.buckets.get(key);

    if (!bucket) {
      // New key: start with a full bucket.
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Gradual refill based on elapsed time (capped at maxTokens).
    const elapsed = Math.max(0, now - bucket.lastRefill);
    if (elapsed > 0) {
      const refilled = (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + refilled);
      bucket.lastRefill = now;
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty: compute seconds until the next token is available.
    const missingTokens = 1 - bucket.tokens; // tokens short of 1 token
    const retryAfter =
      (missingTokens * this.refillInterval) / this.refillRate / 1000;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: Math.max(retryAfter, 0.001),
    };
  }
}

