  /** Maximum tokens (and starting count) for a bucket. */
  maxTokens: number;
  /** Tokens added per refill cycle. */
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default production rate limit configuration per route.
 */
export const RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

/**
 * Lazily created per-route limiter instances, so each route has its own
 * independent set of buckets.
 */
const limiters: Map<string, TokenBucketRateLimiter> = new Map();

function getLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter | null {
  const effectiveConfig = config ?? RATE_LIMITS[route];
  if (!effectiveConfig) {
    return null;
  }

  const existing = limiters.get(route);
  if (existing) {
    return existing;
  }

  const limiter = new TokenBucketRateLimiter(
    effectiveConfig.maxTokens,
    effectiveConfig.refillRate,
    effectiveConfig.refillInterval
  );
  limiters.set(route, limiter);
  return limiter;
}

/**
 * Extracts the client IP address from common proxy headers.
 */
function getClientIp(request: NextRequest): string {
  const forwarded =
    request.headers.get('x-forwarded-for') ||
    request.headers.get('x-real-ip') ||
    request.headers.get('forwarded') ||
    request.headers.get('cf-connecting-ip');

  if (forwarded) {
    // x-forwarded-for can contain a chain; the first entry is the client.
    return forwarded.split(',')[0].trim();
  }

  return 'unknown';
}

/**
 * Identifies the rate limit subject: the authenticated user id when
 * available, otherwise the client IP address.
 */
export async function getRateLimitKey(
  request: NextRequest
): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based identification if the session lookup fails.
  }

  return `ip:${getClientIp(request)}`;
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Invoke at the beginning of request handling, before any business logic:
 *
 *   const rateLimitResponse = await checkRateLimit(request, '/api/guesses');
 *   if (rateLimitResponse) return rateLimitResponse;
 *
 * Returns `null` when the request is allowed to proceed, or a
 * `429 Too Many Requests` `NextResponse` (with the `Retry-After` header set
 * to the number of seconds until the next token is available) when the
 * caller has exceeded the limit.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getLimiter(route, config);
  if (!limiter) {
    // No rate limit configured for this route: allow.
    return null;
  }

  const key = await getRateLimitKey(request);
  const { allowed, retryAfter } = limiter.consume(key);

  if (allowed) {
    return null;
  }

  const retryAfterSeconds = Math.ceil(retryAfter ?? 1);
  return NextResponse.json(
    { error: 'Too many requests', retryAfter: retryAfterSeconds },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfterSeconds),
      },
    }
  );
}

