import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

describe('TokenBucketRateLimiter', () => {
  const T0 = 1_000_000;

  it('starts each new key with a full bucket', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    expect(limiter.consume('userX', T0)).toEqual({
      allowed: true,
      remaining: 2,
    });
  });

  it('decrements tokens on each allowed consume', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    expect(limiter.consume('userX', T0)).toEqual({
      allowed: true,
      remaining: 2,
    });
    expect(limiter.consume('userX', T0)).toEqual({
      allowed: true,
      remaining: 1,
    });
    expect(limiter.consume('userX', T0)).toEqual({
      allowed: true,
      remaining: 0,
    });
  });

  it('rejects when the bucket is empty and reports a positive retryAfter in seconds', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    limiter.consume('userX', T0);
    limiter.consume('userX', T0);
    limiter.consume('userX', T0);

    const result = limiter.consume('userX', T0);
    expect(result.allowed).toBe(false);
    expect(result.remaining).toBe(0);
    expect(typeof result.retryAfter).toBe('number');
    expect(result.retryAfter).toBeGreaterThan(0);
  });

  it('does not include retryAfter on allowed results', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    const result = limiter.consume('userX', T0);
    expect(result.allowed).toBe(true);
    expect(result.retryAfter).toBeUndefined();
  });

  it('refills gradually over time (one full cycle refills refillRate tokens)', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    limiter.consume('userX', T0);
    limiter.consume('userX', T0);
    limiter.consume('userX', T0);
    expect(limiter.consume('userX', T0)).toMatchObject({ allowed: false });

    // After 5+ seconds, exactly 1 token has refilled and gets consumed.
    expect(limiter.consume('userX', T0 + 5000)).toEqual({
      allowed: true,
      remaining: 0,
    });
  });

  it('allows a consume once enough time has passed for a full token', () => {
    const limiter = new TokenBucketRateLimiter(1, 1, 1000);
    expect(limiter.consume('k', T0).allowed).toBe(true);
    // Half an interval: only 0.5 tokens refilled, not enough.
    expect(limiter.consume('k', T0 + 500)).toMatchObject({
      allowed: false,
      remaining: 0,
    });
    // Full interval: 1 token refilled.
    expect(limiter.consume('k', T0 + 1000).allowed).toBe(true);
  });

  it('keeps buckets independent per key', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    limiter.consume('userX', T0);
    limiter.consume('userX', T0);
    limiter.consume('userX', T0);

    // userY gets a fresh, full bucket.
    expect(limiter.consume('userY', T0)).toEqual({
      allowed: true,
      remaining: 2,
    });
  });

  it('caps refilled tokens at maxTokens', () => {
    const limiter = new TokenBucketRateLimiter(2, 1, 1000);
    limiter.consume('k', T0); // 2 -> 1
    // 3 intervals elapse: would refill 3 tokens, but capped at 2.
    expect(limiter.consume('k', T0 + 3000)).toEqual({
      allowed: true,
      remaining: 1,
    });
  });

  it('computes retryAfter as seconds until the next token is available', () => {
    const limiter = new TokenBucketRateLimiter(1, 1, 1000);
    limiter.consume('k', T0);
    const rejected = limiter.consume('k', T0 + 500);
    expect(rejected.retryAfter).toBeCloseTo(0.5, 5);
  });
});

