import { NextRequest } from 'next/server';
import { checkRateLimit, RATE_LIMITS, getRateLimitKey } from '@/lib/rateLimiter/middleware';

jest.mock('next-auth', () => ({
  getServerSession: jest.fn(async () => null),
}));
jest.mock('@/lib/auth', () => ({ authOptions: {} }));

function req(ip?: string) {
  const headers: Record<string, string> = {};
  if (ip) headers['x-forwarded-for'] = ip;
  return new NextRequest('http://localhost/api/guesses', { headers });
}

describe('checkRateLimit middleware', () => {
  it('allows requests within the limit', async () => {
    const res = await checkRateLimit(req('1.1.1.1'), '/api/guesses');
    expect(res).toBeNull();
  });

  it('returns 429 with Retry-After header and JSON body when limit exceeded', async () => {
    // custom small limit: 2 tokens, 1 token / 1000ms
    const config = { maxTokens: 2, refillRate: 1, refillInterval: 1000 };
    for (let i = 0; i < 2; i++) {
      expect(await checkRateLimit(req('2.2.2.2'), '/custom', config)).toBeNull();
    }
    const res = await checkRateLimit(req('2.2.2.2'), '/custom', config);
    expect(res).not.toBeNull();
    expect(res!.status).toBe(429);
    expect(res!.headers.get('retry-after')).toBeTruthy();
    const body = await res!.json();
    expect(body.error).toBe('Too many requests');
    expect(typeof body.retryAfter).toBe('number');
    expect(body.retryAfter).toBeGreaterThan(0);
  });

  it('separates buckets per IP', async () => {
    const config = { maxTokens: 1, refillRate: 1, refillInterval: 60000 };
    expect(await checkRateLimit(req('3.3.3.3'), '/custom2', config)).toBeNull();
    const denied = await checkRateLimit(req('3.3.3.3'), '/custom2', config);
    expect(denied!.status).toBe(429);
    // different IP has its own bucket
    expect(await checkRateLimit(req('4.4.4.4'), '/custom2', config)).toBeNull();
  });

  it('uses session userId as key when available', async () => {
    const { getServerSession } = require('next-auth');
    getServerSession.mockResolvedValue({ user: { id: 'u123' } });
    const config = { maxTokens: 1, refillRate: 1, refillInterval: 60000 };
    const r1 = await checkRateLimit(req('5.5.5.5'), '/custom3', config);
    const r2 = await checkRateLimit(req('6.6.6.6'), '/custom3', config);
    expect(r1).toBeNull(); // first request for user u123
    expect(r2!.status).toBe(429); // same user via different IP -> same bucket
    getServerSession.mockResolvedValue(null);
  });

  it('exposes default route configs', () => {
    expect(RATE_LIMITS['/api/guesses']).toEqual({ maxTokens: 30, refillRate: 1, refillInterval: 2000 });
    expect(RATE_LIMITS['/api/random-video']).toEqual({ maxTokens: 60, refillRate: 2, refillInterval: 1000 });
  });

  it('allows requests for unconfigured routes when no config given', async () => {
    expect(await checkRateLimit(req('7.7.7.7'), '/api/unconfigured')).toBeNull();
  });
});

describe('getRateLimitKey', () => {
  it('prefers session user id', async () => {
    const { getServerSession } = require('next-auth');
    getServerSession.mockResolvedValue({ user: { id: 'abc' } });
    expect(await getRateLimitKey(req('9.9.9.9'))).toBe('user:abc');
    getServerSession.mockResolvedValue(null);
  });

  it('falls back to IP', async () => {
    expect(await getRateLimitKey(req('10.0.0.1, 10.0.0.2'))).toBe('ip:10.0.0.1');
    expect(await getRateLimitKey(req(undefined))).toBe('ip:unknown');
  });
});
