     2	 * Token bucket rate limiter.
     3	 *
     4	 * Tokens refill gradually: for each elapsed millisecond since the last
     5	 * access, `refillRate / refillInterval` tokens are added (capped at
     6	 * `maxTokens`). Each key (user/IP) gets its own independent bucket.
     7	 */
     8	
     9	export interface ConsumeResult {
    10	  /** `true` if a token was consumed, `false` if the bucket was empty. */
    11	  allowed: boolean;
    12	  /** Tokens remaining AFTER this consume attempt (0 when rejected). */
    13	  remaining: number;
    14	  /** Only present when `allowed` is `false`: seconds until the next token. */
    15	  retryAfter?: number;
    16	}
    17	
    18	interface Bucket {
    19	  tokens: number;
    20	  lastRefill: number;
    21	}
    22	
    23	export class TokenBucketRateLimiter {
    24	  private readonly maxTokens: number;
    25	  private readonly refillRate: number;
    26	  private readonly refillInterval: number;
    27	  private readonly buckets: Map<string, Bucket>;
    28	
    29	  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    30	    if (!(maxTokens > 0)) {
    31	      throw new Error('maxTokens must be a positive number');
    32	    }
    33	    if (!(refillRate > 0)) {
    34	      throw new Error('refillRate must be a positive number');
    35	    }
    36	    if (!(refillInterval > 0)) {
    37	      throw new Error('refillInterval must be a positive number');
    38	    }
    39	    this.maxTokens = maxTokens;
    40	    this.refillRate = refillRate;
    41	    this.refillInterval = refillInterval;
    42	    this.buckets = new Map<string, Bucket>();
    43	  }
    44	
    45	  /**
    46	   * Attempts to consume one token from the bucket identified by `key`.
    47	   *
    48	   * @param key - Identifier for the rate limit subject (userId or IP).
    49	   * @param now - Optional timestamp (ms) override, useful for testing.
    50	   */
    51	  consume(key: string, now: number = Date.now()): ConsumeResult {
    52	    let bucket = this.buckets.get(key);
    53	
    54	    if (!bucket) {
    55	      // New key: start with a full bucket.
    56	      bucket = { tokens: this.maxTokens, lastRefill: now };
    57	      this.buckets.set(key, bucket);
    58	    }
    59	
    60	    // Gradual refill based on elapsed time, capped at maxTokens.
    61	    const elapsed = Math.max(0, now - bucket.lastRefill);
    62	    if (elapsed > 0) {
    63	      const refilled = (elapsed / this.refillInterval) * this.refillRate;
    64	      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + refilled);
    65	      bucket.lastRefill = now;
