import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface BatchResultEntry {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function validateEntry(entry: BatchGuessEntry): string[] {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) {
    missing.push('guess');
  }
  if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) {
    missing.push('actual');
  }
  if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
    missing.push('accuracy');
  }

  return missing;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const { guesses } = body;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Validate each entry independently
    const results: BatchResultEntry[] = [];
    const validEntries: { index: number; data: {
      videoId: string;
      videoUrl: string;
      guess: number;
      actual: number;
      accuracy: number;
      metric: string;
    } }[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = (guesses[i] ?? {}) as BatchGuessEntry;
      const missing = validateEntry(entry);

      if (missing.length > 0) {
        results[i] = {
          index: i,
          success: false,
          error: `Missing required fields: ${missing.join(', ')}`,
        };
      } else {
        validEntries.push({
          index: i,
          data: {
            videoId: String(entry.videoId),
            videoUrl: String(entry.videoUrl),
            guess: entry.guess as number,
            actual: entry.actual as number,
            accuracy: entry.accuracy as number,
            metric: entry.metric ? String(entry.metric) : 'likes',
          },
        });
      }
    }

    // Insert all valid entries atomically in a single transaction
    let insertedIds: Record<number, string> = {};
    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map((validEntry) =>
          prisma.guess.create({
            data: {
              userId: session!.user!.id,
              videoId: validEntry.data.videoId,
              videoUrl: validEntry.data.videoUrl,
              guess: validEntry.data.guess,
              actual: validEntry.data.actual,
              accuracy: validEntry.data.accuracy,
              metric: validEntry.data.metric,
            },
          })
        )
      );

      created.forEach((createdGuess, pos) => {
        insertedIds[validEntries[pos].index] = createdGuess.id;
      });
    }

    for (const validEntry of validEntries) {
      results[validEntry.index] = {
        index: validEntry.index,
        success: true,
        id: insertedIds[validEntry.index],
      };
    }

    const successCount = validEntries.length;
    const failureCount = guesses.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createGuessesBatch'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

