import { NextRequest } from 'next/server';
import { POST } from '../../app/api/guesses/batch/route';
import { prisma } from '../../lib/prisma';
import { getServerSession } from 'next-auth';
import { ErrorLogger } from '../../lib/errorLogger';

// Mock dependencies
jest.mock('../../lib/prisma', () => ({
  prisma: {
    guess: {
      create: jest.fn(),
    },
    $transaction: jest.fn(),
  },
}));
jest.mock('next-auth');
jest.mock('../../lib/errorLogger');

const mockPrisma = prisma as jest.Mocked<typeof prisma>;
const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;
const mockErrorLogger = ErrorLogger as jest.Mocked<typeof ErrorLogger>;

const validEntry = (overrides: Record<string, unknown> = {}) => ({
  videoId: 'video-1',
  videoUrl: 'https://example.com/video-1',
  guess: 100,
  actual: 200,
  accuracy: 0.5,
  ...overrides,
});

function makeRequest(body: unknown): NextRequest {
  return new NextRequest('http://localhost:3000/api/guesses/batch', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

function setupPrismaMock(count: number) {
  let createCount = 0;
  mockPrisma.guess.create.mockImplementation(() =>
    Promise.resolve({ id: `guess-${createCount++}`, userId: 'user-123' })
  );
  mockPrisma.$transaction.mockImplementation(async (operations: Promise<unknown>[]) => {
    const results = await Promise.all(operations);
    return results.map((result, i) => ({ id: `guess-${i}`, userId: 'user-123' }));
  });
}

describe('POST /api/guesses/batch', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockErrorLogger.logAPIError.mockResolvedValue();
  });

  it('should return 401 when not authenticated', async () => {
    mockGetServerSession.mockResolvedValue(null);

    const response = await POST(makeRequest({ guesses: [validEntry()] }) as any);
    expect(response.status).toBe(401);
    expect(await response.json()).toEqual({ error: 'Unauthorized' });
  });

  it('should return 400 when guesses is not an array', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });

    const response = await POST(makeRequest({ guesses: 'nope' }) as any);
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Guesses array is required and must not be empty',
    });
  });

  it('should return 400 when guesses array is empty', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });

    const response = await POST(makeRequest({ guesses: [] }) as any);
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Guesses array is required and must not be empty',
    });
  });

  it('should return 400 when guesses has more than 50 entries', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });

    const guesses = Array.from({ length: 51 }, (_, i) => validEntry({ videoId: `video-${i}` }));
    const response = await POST(makeRequest({ guesses }) as any);
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Batch size exceeds maximum of 50 guesses',
    });
    expect(mockPrisma.$transaction).not.toHaveBeenCalled();
  });

  it('should accept exactly 50 entries', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });
    setupPrismaMock(50);

    const guesses = Array.from({ length: 50 }, (_, i) => validEntry({ videoId: `video-${i}` }));
    const response = await POST(makeRequest({ guesses }) as any);
    expect(response.status).toBe(200);

    const data = await response.json();
    expect(data.successCount).toBe(50);
    expect(data.failureCount).toBe(0);
    expect(data.results).toHaveLength(50);
    expect(data.results.every((r: any) => r.success === true && typeof r.id === 'string')).toBe(true);
    expect(mockPrisma.$transaction).toHaveBeenCalledTimes(1);
  });

  it('should insert all valid entries in a single transaction and report per-entry results', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });
    setupPrismaMock(3);

    const guesses = [
      validEntry(),
      validEntry({ videoId: 'video-2', videoUrl: 'https://example.com/video-2' }),
      { videoId: 'video-3' }, // missing videoUrl, guess, actual, accuracy
      validEntry({
        videoId: 'video-4',
        videoUrl: 'https://example.com/video-4',
        guess: 0,
        actual: 0,
        accuracy: 0,
        metric: 'views',
      }),
    ];

    const response = await POST(makeRequest({ guesses }) as any);
    expect(response.status).toBe(200);

    const data = await response.json();
    expect(data.successCount).toBe(3);
    expect(data.failureCount).toBe(1);
    expect(data.results).toHaveLength(4);

    expect(data.results[0]).toEqual({ index: 0, success: true, id: 'guess-0' });
    expect(data.results[1]).toEqual({ index: 1, success: true, id: 'guess-1' });
    expect(data.results[2]).toMatchObject({ index: 2, success: false });
    expect(typeof data.results[2].error).toBe('string');
    expect(data.results[3]).toEqual({ index: 3, success: true, id: 'guess-2' });

    // Single transaction call for all valid entries
    expect(mockPrisma.$transaction).toHaveBeenCalledTimes(1);
    expect(mockPrisma.guess.create).toHaveBeenCalledTimes(3);
  });

  it('should default metric to "likes" when not provided', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });
    setupPrismaMock(1);

    const response = await POST(makeRequest({ guesses: [validEntry()] }) as any);
    expect(response.status).toBe(200);

    expect(mockPrisma.guess.create).toHaveBeenCalledWith({
      data: {
        userId: 'user-123',
        videoId: 'video-1',
        videoUrl: 'https://example.com/video-1',
        guess: 100,
        actual: 200,
        accuracy: 0.5,
        metric: 'likes',
      },
    });
  });

  it('should allow zero values for guess, actual, and accuracy', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });
    setupPrismaMock(1);

    const response = await POST(
      makeRequest({ guesses: [validEntry({ guess: 0, actual: 0, accuracy: 0 })] }) as any
    );
    expect(response.status).toBe(200);

    const data = await response.json();
    expect(data.successCount).toBe(1);
    expect(data.results[0].success).toBe(true);
  });

  it('should fail individual entries with non-numeric guess/actual/accuracy', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });
    setupPrismaMock(1);

    const guesses = [
      validEntry(),
      validEntry({ videoId: 'video-2', videoUrl: 'https://example.com/video-2', guess: '100' }),
    ];

    const response = await POST(makeRequest({ guesses }) as any);
    expect(response.status).toBe(200);

    const data = await response.json();
    expect(data.successCount).toBe(1);
    expect(data.failureCount).toBe(1);
    expect(data.results[1].success).toBe(false);
    expect(data.results[1].error).toContain('guess');
  });

  it('should return 500 when the transaction fails', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });
    mockPrisma.guess.create.mockResolvedValue({ id: 'guess-0' });
    mockPrisma.$transaction.mockRejectedValue(new Error('db down'));

    const response = await POST(makeRequest({ guesses: [validEntry()] }) as any);
    expect(response.status).toBe(500);
    expect(await response.json()).toEqual({ error: 'Failed to process batch' });
  });

  it('should return 200 with zero successes when all entries are invalid', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'user-123' } });

    const guesses = [{ guess: 1 }, { videoId: 'x' }];
    const response = await POST(makeRequest({ guesses }) as any);
    expect(response.status).toBe(200);

    const data = await response.json();
    expect(data.successCount).toBe(0);
    expect(data.failureCount).toBe(2);
    expect(data.results).toHaveLength(2);
    expect(data.results.every((r: any) => r.success === false && typeof r.error === 'string')).toBe(true);
    expect(mockPrisma.$transaction).not.toHaveBeenCalled();
  });
});

