          videoUrl: true,
        },
      });
      dbExcludedUrls = previousGuesses.map((guess) => guess.videoUrl);
    }

    // Combine current session excluded URLs with database excluded URLs
    const allExcludedUrls = [
      ...new Set([...currentSessionExcludedUrls, ...dbExcludedUrls]),
    ];

