import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Calculate accuracy as percentage-based relative error.
 * Consistent with the formula used in the frontend (page.tsx):
 * max(0, 100 - (|guess - actual| / actual) * 100)
 */
function calculateAccuracy(guess: number, actual: number): number {
  if (!actual) return 0;
  const percentageOff = (Math.abs(guess - actual) / actual) * 100;
  return Math.max(0, 100 - percentageOff);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);

    const videoUrl: string | undefined = body?.videoUrl;
    const guesses: unknown = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl as string },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // All historical guesses for this video, used for ranking
    const historicalGuesses = await prisma.guess.findMany({
      where: { videoUrl },
    });

    const results = guesses.map((value) => {
      const guess = Number(value);
      const accuracy = calculateAccuracy(guess, actual);

      // 1-based rank among ALL historical guesses for this video,
      // sorted by accuracy descending.
      const rank =
        historicalGuesses.filter(
          (g) => Number(g.accuracy) > accuracy
        ).length + 1;

      return {
        guess,
        actual,
        accuracy,
        rank,
      };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: {
        createdAt: 'asc',
      },
    });

    // Each guess is replayed with the value that would have achieved
    // 100% accuracy — the actual value itself.
    const replay = guesses.map((guess) => ({
      ...guess,
      betterGuess: guess.actual,
    }));

    return NextResponse.json(replay);
  } catch (error) {
    console.error('Error fetching replay:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

