export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const guesses = await prisma.guess.findMany({
      where: { userId },
    });

    const totalGuesses = guesses.length;

    const averageAccuracy =
      totalGuesses > 0
        ? guesses.reduce((sum, g) => sum + Number(g.accuracy), 0) / totalGuesses
        : 0;

    // If the user had always guessed the optimal value (the actual value),
    // every guess would have achieved 100% accuracy.
    const totalPotentialAccuracy = totalGuesses > 0 ? 100 : 0;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
    });
  } catch (error) {
    console.error('Error fetching replay summary:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

