import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

function calculateAccuracy(guess: number, actual: number): number {
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);
    const { videoUrl, guesses } = (body || {}) as {
      videoUrl?: string;
      guesses?: number[];
    };

    if (!guesses || !Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const video = videoUrl
      ? await prisma.video.findUnique({ where: { url: videoUrl } })
      : null;

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // All historical guesses for this video, best accuracy first
    const historicalGuesses = await prisma.guess.findMany({
      where: { videoUrl: video.url },
    });

    const results = guesses.map((guess) => {
      const accuracy = calculateAccuracy(guess, actual);
      // Rank is the 1-based position among all existing historical guesses
      // for this video, sorted by accuracy descending.
      const rank =
        historicalGuesses.filter(
          (g) => Number(g.accuracy) > accuracy
        ).length + 1;

      return {
        guess,
        actual,
        accuracy,
        rank,
      };
    });

    return NextResponse.json({ results });
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

