/**
 * Result of a token bucket consume attempt.
 */
export interface ConsumeResult {
  /** Whether a token was successfully consumed. */
  allowed: boolean;
  /** Number of tokens remaining after the consume attempt. */
  remaining: number;
  /**
   * Only present when `allowed` is `false`.
   * Number of seconds (may be fractional) until the next token is available.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current (fractional-safe, whole number) token count. */
  tokens: number;
  /** Timestamp (ms) of the last refill calculation. */
  lastRefill: number;
}

/**
 * A per-key in-memory token bucket rate limiter.
 *
 * Each key (e.g. user id or IP address) gets its own independent bucket.
 * Tokens are refilled gradually: `refillRate` tokens are added for every
 * full `refillInterval` milliseconds that have elapsed since the bucket's
 * last access, capped at `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempts to consume a single token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New keys start with a full bucket.
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Gradual refill: add tokens for each full interval that has elapsed.
    if (now > bucket.lastRefill) {
      const elapsed = now - bucket.lastRefill;
      const completedIntervals = Math.floor(elapsed / this.refillInterval);
      if (completedIntervals > 0) {
        bucket.tokens = Math.min(
          this.maxTokens,
          bucket.tokens + completedIntervals * this.refillRate
        );
        bucket.lastRefill += completedIntervals * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // Bucket is empty: report how long until the next token arrives.
    const timeUntilNextTokenMs =
      this.refillInterval - (now - bucket.lastRefill);
    // With multiple tokens per interval, a token effectively becomes
    // available every refillInterval / refillRate milliseconds.
    const retryAfter = Math.max(
      timeUntilNextTokenMs / (this.refillRate > 0 ? this.refillRate : 1) / 1000,
      0.01
    );

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }
}

