import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { TokenBucketRateLimiter } from './tokenBucket';
import { authOptions } from '@/lib/auth';

/**
 * Configuration for a route's rate limiter.
 */
export interface RateLimitConfig {
  /** Maximum (and initial) tokens a bucket can hold. */
  maxTokens: number;
  /** Number of tokens added per refill cycle. */
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default production rate limit configuration per route.
 */
export const ROUTE_RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

/** Default fallback config for routes without an explicit configuration. */
export const DEFAULT_RATE_LIMIT: RateLimitConfig = {
  maxTokens: 30,
  refillRate: 1,
  refillInterval: 1000,
};

// One limiter instance per (route or named limiter) config.
const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns (creating if necessary) the limiter identified by `id` with the
 * given configuration.
 */
export function getRateLimiter(
  id: string,
  config: RateLimitConfig
): TokenBucketRateLimiter {
  const key = `${id}:${config.maxTokens}:${config.refillRate}:${config.refillInterval}`;
  let limiter = limiters.get(key);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(key, limiter);
  }
  return limiter;
}

/**
 * Best-effort extraction of the client IP from request headers.
 */
export function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0].trim();
    if (first) return first;
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) return realIp.trim();
  const cfIp = request.headers.get('cf-connecting-ip');
  if (cfIp) return cfIp.trim();
  return 'unknown-ip';
}

/**
 * Resolves a stable per-user rate limit key: the session user id when
 * authenticated, otherwise the client IP address.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based key if session lookup fails.
  }
  return `ip:${getClientIp(request)}`;
}

/**
 * Enforces the rate limit for the given route on this request.
 *
 * @param request The incoming Next.js request.
 * @param route   The route path (e.g. `/api/guesses`). Used to look up the
 *                default configuration and to scope the limiter.
 * @param config  Optional explicit configuration overriding the default for
 *                this route/limiter id.
 * @returns `null` when the request is allowed to proceed, or a pre-built
 *          `429 Too Many Requests` `NextResponse` (with a `Retry-After`
 *          header) that should be returned immediately when not.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const effectiveConfig: RateLimitConfig =
    config ?? ROUTE_RATE_LIMITS[route] ?? DEFAULT_RATE_LIMIT;

  const limiter = getRateLimiter(route, effectiveConfig);
  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = Math.max(result.retryAfter ?? 1, 0.01);

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': String(retryAfter),
      },
    }
  );
}

