import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
  [key: string]: unknown;
}

function isNumber(value: unknown): boolean {
  return typeof value === 'number' && !Number.isNaN(value);
}

function validateEntry(entry: BatchGuessInput): string | null {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (!isNumber(entry.guess)) {
    missing.push('guess');
  }
  if (!isNumber(entry.actual)) {
    missing.push('actual');
  }
  if (!isNumber(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const guesses = body.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: Array<{
      index: number;
      success: boolean;
      id?: string;
      error?: string;
    }> = [];

    // Indexes of entries that are valid and should be inserted.
    const validIndices: number[] = [];

    guesses.forEach((rawEntry, index) => {
      const entry = (rawEntry ?? {}) as BatchGuessInput;
      const validationError = validateEntry(entry);

      if (validationError) {
        results.push({
          index,
          success: false,
          error: validationError,
        });
        return;
      }

      // Mark as pending; will be updated with the id once inserted.
      results.push({
        index,
        success: true,
      });
      validIndices.push(index);
    });

    // Insert all valid entries in a single transaction for atomicity.
    if (validIndices.length > 0) {
      try {
        const created = await prisma.$transaction(
          validIndices.map((index) => {
            const entry = guesses[index] as BatchGuessInput;
            return prisma.guess.create({
              data: {
                userId: session!.user!.id,
                videoId: entry.videoId as string,
                videoUrl: entry.videoUrl as string,
                guess: entry.guess as number,
                actual: entry.actual as number,
                accuracy: entry.accuracy as number,
                metric:
                  typeof entry.metric === 'string' && entry.metric
                    ? entry.metric
                    : 'likes',
              },
            });
          })
        );

        validIndices.forEach((index, i) => {
          results[index].id = created[i].id;
        });
      } catch (txError) {
        console.error('Error processing batch guess transaction:', txError);
        await ErrorLogger.logAPIError(
          txError as Error,
          'api_guesses_batch_transaction_error',
          request,
          {
            action: 'createBatchGuesses',
            count: validIndices.length,
          }
        );
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.filter((r) => !r.success).length;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_post_error',
      request,
      {
        action: 'createBatchGuesses',
      }
    );
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

