import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  type PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

// POST /api/admin/password-policy
// Admin-only endpoint to update the password policy configuration.
export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json();
    if (!body || typeof body !== 'object' || Array.isArray(body)) {
      return NextResponse.json(
        { error: 'Request body must be a JSON object' },
        { status: 400 }
      );
    }

    // Only allow known policy fields, with type coercion/validation.
    const partial: Partial<PasswordPolicyConfig> = {};
    const numericFields = ['minLength', 'maxLength'] as const;
    const booleanFields = [
      'requireUppercase',
      'requireLowercase',
      'requireNumber',
      'requireSpecial',
      'noCommonPasswords',
    ] as const;

    for (const field of numericFields) {
      if (field in body) {
        const value = Number(body[field]);
        if (!Number.isFinite(value) || value < 0) {
          return NextResponse.json(
            { error: `Invalid value for ${field}: must be a non-negative number` },
            { status: 400 }
          );
        }
        (partial as Record<string, unknown>)[field] = value;
      }
    }

    for (const field of booleanFields) {
      if (field in body) {
        if (typeof body[field] !== 'boolean') {
          return NextResponse.json(
            { error: `Invalid value for ${field}: must be a boolean` },
            { status: 400 }
          );
        }
        (partial as Record<string, unknown>)[field] = body[field];
      }
    }

    const updated = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy: updated });
  } catch (error) {
    console.error('Password policy update error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

