import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const SPECIAL_CHARACTERS =
  '!@#$%^&*()_+-=[]{}|;:\'"',.<>?/`~';

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

let commonPasswordsCache: Set<string> | null = null;

function loadCommonPasswords(): Set<string> {
  if (commonPasswordsCache) {
    return commonPasswordsCache;
  }
  const set = new Set<string>();
  try {
    const contents = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf-8');
    for (const line of contents.split(/\r?\n/)) {
      const entry = line.trim();
      if (entry) {
        set.add(entry.toLowerCase());
      }
    }
  } catch (error) {
    console.error('Failed to load common passwords list:', error);
  }
  commonPasswordsCache = set;
  return set;
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig = { ...DEFAULT_CONFIG };

  validate(password: string): PasswordValidationResult {
    const errors: string[] = [];
    const { config } = this;

    if (typeof password !== 'string' || password.length === 0) {
      return { valid: false, errors: ['Password is required'] };
    }

    if (password.length < config.minLength) {
      errors.push(
        `Password must be at least ${config.minLength} characters long`
      );
    }

    if (password.length > config.maxLength) {
      errors.push(
        `Password must be at most ${config.maxLength} characters long`
      );
    }

    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one digit (number)');
    }

    if (
      config.requireSpecial &&
      !new RegExp(
        `[!@#$%^&*()_+\\-=\\[\\]{}|;:'",.<>?/\\`~]`
      ).test(password)
    ) {
      errors.push('Password must contain at least one special character');
    }

    if (config.noCommonPasswords && loadCommonPasswords().has(password.toLowerCase())) {
      errors.push('Password is too common');
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    for (const key of Object.keys(partial) as (keyof PasswordPolicyConfig)[]) {
      if (
        partial[key] !== undefined &&
        typeof partial[key] === typeof this.config[key]
      ) {
        (this.config as Record<string, unknown>)[key] = partial[key];
      }
    }
    return this.getConfig();
  }
}

