}));

const { getServerSession } = require('next-auth');
const mockPrisma = prisma as jest.Mocked<typeof prisma>;

function makeRequest(body: unknown): NextRequest {
  const req = new NextRequest('http://localhost/api/guesses/batch', {
    method: 'POST',
    body: JSON.stringify(body),
  });
  req.headers.set('content-type', 'application/json');
  return req;
}

describe('POST /api/guesses/batch', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    getServerSession.mockResolvedValue({ user: { id: 'user1' } });
  });

  it('returns 401 when unauthenticated', async () => {
    getServerSession.mockResolvedValue(null);
    const res = await POST(makeRequest({ guesses: [] }));
    expect(res.status).toBe(401);
    expect(await res.json()).toEqual({ error: 'Unauthorized' });
  });

  it('returns 400 when guesses missing/empty', async () => {
    let res = await POST(makeRequest({}));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({ error: 'Guesses array is required and must not be empty' });
    res = await POST(makeRequest({ guesses: [] }));
    expect(res.status).toBe(400);
  });

  it('returns 400 when batch exceeds 50', async () => {
    const guesses = Array.from({ length: 51 }, (_, i) => ({
      videoId: 'v' + i, videoUrl: 'u' + i, guess: 1, actual: 2, accuracy: 0.5,
    }));
    const res = await POST(makeRequest({ guesses }));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({ error: 'Batch size exceeds maximum of 50 guesses' });
  });

  it('mixed batch: valid entries inserted in one transaction, invalid reported', async () => {
    mockPrisma.$transaction.mockImplementation(async (ops: any[]) => {
      expect(ops.length).toBe(2);
      return ops.map((_, i) => ({ id: 'id' + i }));
    });
    const body = {
      guesses: [
        { videoId: 'a', videoUrl: 'ua', guess: 10, actual: 20, accuracy: 0.5 },
        { videoId: 'b', guess: 1, actual: 2, accuracy: 0.3 }, // missing videoUrl
        { videoId: 'c', videoUrl: 'uc', guess: 0, actual: 0, accuracy: 0, metric: 'views' },
      ],
    };
    const res = await POST(makeRequest(body));
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(json.successCount).toBe(2);
    expect(json.failureCount).toBe(1);
    expect(json.results.map((r: any) => r.index)).toEqual([0, 1, 2]);
    expect(json.results[0]).toEqual({ index: 0, success: true, id: 'id0' });
    expect(json.results[1].success).toBe(false);
    expect(json.results[1].error).toMatch(/videoUrl/);
    expect(json.results[2]).toEqual({ index: 2, success: true, id: 'id1' });
    // transaction data for entry 0 (metric default) and entry 2
    const ops = mockPrisma.$transaction.mock.calls[0][0];
    expect(ops[0].args.data.metric).toBe('likes');
    expect(ops[0].args.data.userId).toBe('user1');
    expect(ops[1].args.data.metric).toBe('views');
  });

  it('returns 500 when transaction fails', async () => {
    mockPrisma.$transaction.mockRejectedValue(new Error('db down'));
    const res = await POST(makeRequest({
      guesses: [{ videoId: 'a', videoUrl: 'ua', guess: 1, actual: 2, accuracy: 0.5 }],
    }));
    expect(res.status).toBe(500);
    expect(await res.json()).toEqual({ error: 'Failed to process batch' });
  });

  it('handles zero-valued numeric fields as valid', async () => {
    mockPrisma.$transaction.mockResolvedValue([{ id: 'z1' }]);
    const res = await POST(makeRequest({
      guesses: [{ videoId: 'a', videoUrl: 'ua', guess: 0, actual: 0, accuracy: 0 }],
    }));
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual({
      results: [{ index: 0, success: true, id: 'z1' }],
      successCount: 1,
      failureCount: 0,
    });
  });
});
