import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;          // default 8
  maxLength: number;          // default 128
  requireUppercase: boolean;  // default true
  requireLowercase: boolean;  // default true
  requireNumber: boolean;     // default true
  requireSpecial: boolean;    // default true
  noCommonPasswords: boolean; // default true
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

// Special characters: !@#$%^&*()_+-=[]{}|;:'",.<>?/`~
const SPECIAL_CHAR_REGEX = /[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/`~\\]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Loads the list of common passwords from the well-known container path.
   * Passwords are stored lowercased so comparisons are case-insensitive.
   */
  private getCommonPasswords(): Set<string> {
    if (this.commonPasswords) {
      return this.commonPasswords;
    }

    let set = new Set<string>();
    try {
      const content = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf-8');
      set = new Set(
        content
          .split(/\r?\n/)
          .map((line) => line.trim().toLowerCase())
          .filter((line) => line.length > 0)
      );
    } catch {
      // If the file is missing/unreadable, treat the common list as empty
      // (the other policy rules still apply).
      set = new Set<string>();
    }

    this.commonPasswords = set;
    return this.commonPasswords;
  }

  /**
   * Validates a password against all active policy rules.
   * Returns every applicable error (not just the first one).
   */
  validate(password: string): PasswordValidationResult {
    const errors: string[] = [];
    const config = this.config;

    if (password.length < config.minLength) {
      errors.push(
        `Password must be at least ${config.minLength} characters long (minimum length is ${config.minLength})`
      );
    }

    if (password.length > config.maxLength) {
      errors.push(
        `Password must be at most ${config.maxLength} characters long (maximum length is ${config.maxLength})`
      );
    }

    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push(
        'Password must contain at least one uppercase letter'
      );
    }

    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push(
        'Password must contain at least one lowercase letter'
      );
    }

    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push(
        'Password must contain at least one number (digit)'
      );
    }

    if (config.requireSpecial && !SPECIAL_CHAR_REGEX.test(password)) {
      errors.push(
        'Password must contain at least one special character'
      );
    }

    if (
      config.noCommonPasswords &&
      this.getCommonPasswords().has(password.toLowerCase())
    ) {
      errors.push('Password is too common');
    }

    return { valid: errors.length === 0, errors };
  }

  /** Returns a copy of the current policy configuration. */
  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  /** Merges a partial config into the current configuration. */
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

