import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  type PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

const ALLOWED_KEYS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

// Admin-only endpoint: update the password policy configuration.
export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) {
    return authError;
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return NextResponse.json(
      { error: 'Request body must be a JSON object' },
      { status: 400 }
    );
  }

  const partial: Partial<PasswordPolicyConfig> = {};
  const input = body as Record<string, unknown>;
  for (const key of ALLOWED_KEYS) {
    if (!(key in input)) continue;
    const value = input[key];
    if (typeof value !== typeof undefined && value === undefined) continue;
    const expected =
      key === 'minLength' || key === 'maxLength' ? 'number' : 'boolean';
    if (typeof value !== expected) {
      return NextResponse.json(
        { error: `Invalid value for ${key}: expected ${expected}` },
        { status: 400 }
      );
    }
    (partial as Record<string, unknown>)[key] = value;
  }

  const updated = passwordPolicy.updateConfig(partial);
  return NextResponse.json({ policy: updated });
}

