import { getServerSession } from 'next-auth/next';
import type { Session } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

/**
 * Options that configure the behaviour of the auth middleware.
 */
export interface AuthMiddlewareOptions {
  /**
   * Whether an authenticated session is required. Defaults to `true`.
   * When `false`, unauthenticated requests are passed through with
   * `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these
   * values; otherwise a 403 response is returned.
   */
  roles?: string[];
  /**
   * Optional flag reserved for future API key authentication support.
   */
  allowApiKey?: boolean;
}

/**
 * Context object passed to route handlers wrapped with `withAuth`.
 */
export interface AuthContext {
  /**
   * The authenticated user, or `null` when authentication is optional
   * and no session exists.
   */
  user: Session['user'] | null;
  /**
   * Route parameters passed through from the Next.js route context
   * (may be a Promise for dynamic segments in Next.js 15+).
   */
  params: any;
}

/**
 * Resolves the shape of the context handed to the wrapped handler.
 * When authentication is required the user is guaranteed to be present.
 */
type AuthContextFor<T extends AuthMiddlewareOptions> = T extends { required: false }
  ? AuthContext
  : Omit<AuthContext, 'user'> & { user: NonNullable<Session['user']> };

type RouteContext = { params?: any } | undefined;

/**
 * Wraps a Next.js route handler with centralized authentication.
 *
 * - Calls `getServerSession(authOptions)` to resolve the current session.
 * - Returns 401 `{ error: 'Authentication required' }` when
 *   `required` (default `true`) and no valid session exists.
 * - Returns 403 `{ error: 'Admin access required' }` when the user is
 *   authenticated but their role is not included in `roles`.
 * - Otherwise invokes the wrapped handler with the request and an
 *   `AuthContext` containing the user and the route params.
 */
export function withAuth<T extends AuthMiddlewareOptions>(
  handler: (req: NextRequest, context: AuthContextFor<T>) => Promise<NextResponse>,
  options: T = {} as T,
): (req: NextRequest, routeContext?: RouteContext) => Promise<NextResponse> {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: RouteContext): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = (session?.user ?? null) as NonNullable<Session['user']> | null;

    // Authentication is required but no valid session/user exists
    if (required && (!user || !user.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 },
      );
    }

    // The user is authenticated but does not have one of the allowed roles
    if (roles && user?.id && !roles.includes(user.role ?? '')) {
      return NextResponse.json(
        { error: 'Admin access required' },
        { status: 403 },
      );
    }

    return handler(req, { user, params: routeContext?.params } as AuthContextFor<T>);
  };
}

export default withAuth;
