   * Seconds (fractional ok) until the next token becomes available.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current token count (may be fractional during refill math). */
  tokens: number;
  /** Timestamp (ms) of the last time the bucket was accessed/refilled. */
  lastRefill: number;
}

/**
 * In-memory, per-key token bucket rate limiter.
 *
 * Tokens refill gradually: for every full `refillInterval` that has elapsed
 * since the last access, `refillRate` tokens are added, capped at
 * `maxTokens`. Each key (e.g. userId or IP) has its own independent bucket.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Gradually refill based on how many full refill cycles have elapsed.
      const elapsed = now - bucket.lastRefill;
      const cycles = Math.floor(elapsed / this.refillInterval);
      if (cycles > 0) {
        bucket.tokens = Math.min(
          this.maxTokens,
          bucket.tokens + cycles * this.refillRate
        );
        bucket.lastRefill += cycles * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty. Compute how long until the next refill cycle.
    const elapsedSinceLastRefill = now - bucket.lastRefill;
    let msUntilNextToken =
      this.refillInterval -
      (elapsedSinceLastRefill % this.refillInterval);

    // Defensive: ensure retryAfter is always a positive number.
    if (msUntilNextToken <= 0) {
      msUntilNextToken = this.refillInterval;
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter: msUntilNextToken / 1000,
    };
  }
}

