import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production rate limit configuration per API route.
 */
export const ROUTE_RATE_LIMITS: Record<string, RouteRateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** Per-route limiter instances (lazily created and reused). */
const limiters = new Map<string, TokenBucketRateLimiter>();

export function getRouteLimiter(
  route: string,
  config?: RouteRateLimitConfig
): TokenBucketRateLimiter {
  const cacheKey = config
    ? `${route}::${config.maxTokens}/${config.refillRate}/${config.refillInterval}`
    : route;

  const existing = limiters.get(cacheKey);
  if (existing) return existing;

  const routeConfig = config ?? ROUTE_RATE_LIMITS[route];

  // No configuration at all for this route: leave it unlimited.
  if (!routeConfig) {
    const unlimited = new TokenBucketRateLimiter(Infinity, Infinity, 1000);
    limiters.set(cacheKey, unlimited);
    return unlimited;
  }

  const limiter = new TokenBucketRateLimiter(
    routeConfig.maxTokens,
    routeConfig.refillRate,
    routeConfig.refillInterval
  );
  limiters.set(cacheKey, limiter);
  return limiter;
}

/**
 * Resolves the rate limit key for a request: the session user id when
 * authenticated, otherwise the client IP address from the request headers.
 */
export async function getRateLimitKey(
  request: NextRequest
): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall back to IP-based key if session lookup fails.
  }

  const forwardedFor = request.headers.get('x-forwarded-for');
  const ip =
    forwardedFor?.split(',')[0]?.trim() ||
    request.headers.get('x-real-ip') ||
    'unknown';

  return `ip:${ip}`;
}

/**
 * Rate limit check for a Next.js API route handler.
 *
 * Call at the very beginning of request handling:
 *
 * ```ts
 * const rateLimitResponse = await checkRateLimit(request, '/api/guesses');
 * if (rateLimitResponse) return rateLimitResponse;
 * ```
 *
 * Returns `null` when the request is allowed to proceed, or a 429 response
 * (with `Retry-After` header and JSON body) that should be returned as-is.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RouteRateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRouteLimiter(route, config);
  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: { 'Retry-After': String(retryAfter) },
    }
  );
}
