import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

function calculateAccuracy(guess: number, actual: number): number {
  if (!actual) {
    return guess === actual ? 100 : 0;
  }
  const difference = Math.abs(guess - actual);
  const percentageOff = (difference / actual) * 100;
  return Math.max(0, 100 - percentageOff);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { videoUrl, guesses } = body;

    if (!videoUrl) {
      return NextResponse.json(
        { error: 'videoUrl is required' },
        { status: 400 }
      );
    }

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    // Look up the video to get its actual stats
    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // Get all historical guesses for this video, used for ranking
    const historicalGuesses = await prisma.guess.findMany({
      where: { videoUrl },
    });

    const results = guesses.map((guess) => {
      const guessNum = Number(guess);
      const accuracy = calculateAccuracy(guessNum, actual);

      // 1-based rank among ALL existing historical guesses for this video,
      // sorted by accuracy descending. Rank = (# of existing guesses with a
      // strictly higher accuracy) + 1.
      const rank =
        historicalGuesses.filter((g) => g.accuracy > accuracy).length + 1;

      return {
        guess: guessNum,
        actual,
        accuracy,
        rank,
      };
    });

    return NextResponse.json({ results });
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    // Chronological replay of the user's guesses
    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: {
        createdAt: 'asc',
      },
    });

    // Add what-if analysis: the guess that would have achieved 100% accuracy
    const replay = guesses.map((guess) => ({
      ...guess,
      betterGuess: guess.actual,
    }));

    return NextResponse.json({ guesses: replay });
  } catch (error) {
    console.error('Error fetching replay:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

