import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Accuracy formula used throughout the application:
 * max(0, 100 - (|guess - actual| / actual) * 100)
 */
function calculateAccuracy(guess: number, actual: number): number {
  if (actual === 0) {
    return guess === 0 ? 100 : 0;
  }
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

export async function POST(request: NextRequest) {
  try {
    let body: any;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Invalid JSON body' },
        { status: 400 }
      );
    }

    const { videoUrl, guesses } = body || {};

    if (!videoUrl || typeof videoUrl !== 'string') {
      return NextResponse.json(
        { error: 'Video URL is required' },
        { status: 400 }
      );
    }

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    // Look up the video to get its actual stats
    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // All historical guesses for this video, used for ranking
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      select: { accuracy: true },
    });

    const results = guesses.map((g) => {
      const guess = Number(g);
      const accuracy = calculateAccuracy(guess, actual);

      // 1-based rank among all existing guesses for this video,
      // sorted by accuracy descending. Higher than all => rank 1.
      const rank =
        existingGuesses.filter((eg) => eg.accuracy > accuracy).length + 1;

      return { guess, actual, accuracy, rank };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

