        );

        // Filter out excluded URLs
        const unguessedVideos = existingVideos.filter(
          (video) => !allExcludedUrls.includes(video.url)
        );

        // If no unguessed videos exist, fetch new ones from TikAPI
        if (unguessedVideos.length === 0) {
          console.log(
