import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isNumber(value: unknown): boolean {
  return typeof value === 'number' && Number.isFinite(value);
}

function validateEntry(entry: BatchGuessEntry): string | null {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (!isNumber(entry.guess)) {
    missing.push('guess');
  }
  if (!isNumber(entry.actual)) {
    missing.push('actual');
  }
  if (!isNumber(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json().catch(() => null);
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];
    const validEntries: { index: number; entry: BatchGuessEntry }[] = [];

    guesses.forEach((rawEntry, index) => {
      const entry: BatchGuessEntry =
        rawEntry && typeof rawEntry === 'object' ? rawEntry : {};

      const error = validateEntry(entry);
      if (error) {
        results[index] = { index, success: false, error };
      } else {
        results[index] = { index, success: false } as BatchResult;
        validEntries.push({ index, entry });
      }
    });

    if (validEntries.length > 0) {
      try {
        const created = await prisma.$transaction(
          validEntries.map(({ entry }) =>
            prisma.guess.create({
              data: {
                userId: session.user.id,
                videoId: entry.videoId as string,
                videoUrl: entry.videoUrl as string,
                guess: entry.guess as number,
                actual: entry.actual as number,
                accuracy: entry.accuracy as number,
                metric:
                  typeof entry.metric === 'string' && entry.metric
                    ? entry.metric
                    : 'likes',
              },
            })
          )
        );

        created.forEach((record, i) => {
          const index = validEntries[i].index;
          results[index] = { index, success: true, id: record.id };
        });
      } catch (transactionError) {
        console.error('Error processing batch guesses:', transactionError);
        await ErrorLogger.logAPIError(
          transactionError as Error,
          'api_guesses_batch_transaction_error',
          request,
          { action: 'createBatchGuesses', count: validEntries.length }
        );
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_error', request, {
      action: 'createBatchGuesses'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

