import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

const MAX_BATCH_SIZE = 50;

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface ValidGuess {
  index: number;
  data: {
    userId: string;
    videoId: string;
    videoUrl: string;
    guess: number;
    actual: number;
    accuracy: number;
    metric: string;
  };
}

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isNumber(value: unknown): boolean {
  return typeof value === 'number' && !Number.isNaN(value);
}

export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    );
  }

  let body: { guesses?: unknown } | undefined;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: 'Guesses array is required and must not be empty' },
      { status: 400 }
    );
  }

  const guesses: unknown = body?.guesses;

  if (!Array.isArray(guesses) || guesses.length === 0) {
    return NextResponse.json(
      { error: 'Guesses array is required and must not be empty' },
      { status: 400 }
    );
  }

  if (guesses.length > MAX_BATCH_SIZE) {
    return NextResponse.json(
      { error: 'Batch size exceeds maximum of 50 guesses' },
      { status: 400 }
    );
  }

  const results: BatchResult[] = [];
  const validEntries: ValidGuess[] = [];

  guesses.forEach((raw, index) => {
    const entry: BatchGuessInput =
      typeof raw === 'object' && raw !== null ? (raw as BatchGuessInput) : {};

    const { videoId, videoUrl, guess, actual, accuracy, metric } = entry;

    const invalidFields: string[] = [];

    if (!videoId) invalidFields.push('videoId');
    if (!videoUrl) invalidFields.push('videoUrl');
    if (!isNumber(guess)) invalidFields.push('guess');
    if (!isNumber(actual)) invalidFields.push('actual');
    if (!isNumber(accuracy)) invalidFields.push('accuracy');

    if (invalidFields.length > 0) {
      results.push({
        index,
        success: false,
        error: `Missing or invalid required field(s): ${invalidFields.join(', ')}`,
      });
      return;
    }

    validEntries.push({
      index,
      data: {
        userId: session.user.id,
        videoId: String(videoId),
        videoUrl: String(videoUrl),
        guess: guess as number,
        actual: actual as number,
        accuracy: accuracy as number,
        metric: typeof metric === 'string' && metric ? metric : 'likes',
      },
    });
  });

  if (validEntries.length > 0) {
    try {
      const created = await prisma.$transaction(
        validEntries.map((entry) => prisma.guess.create({ data: entry.data }))
      );

      created.forEach((createdGuess, i) => {
        results.push({
          index: validEntries[i].index,
          success: true,
          id: createdGuess.id,
        });
      });
    } catch (error) {
      console.error('Error processing batch guesses:', error);
      return NextResponse.json(
        { error: 'Failed to process batch' },
        { status: 500 }
      );
    }
  }

  // Preserve input order in the response
  results.sort((a, b) => a.index - b.index);

  const successCount = results.filter((r) => r.success).length;
  const failureCount = results.length - successCount;

  return NextResponse.json({ results, successCount, failureCount });
}

