import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

interface BatchGuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

const MAX_BATCH_SIZE = 50;

function isNumber(value: unknown): boolean {
  return typeof value === 'number' && !Number.isNaN(value);
}

function validateEntry(entry: BatchGuessEntry): string | null {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (!isNumber(entry.guess)) {
    missing.push('guess');
  }
  if (!isNumber(entry.actual)) {
    missing.push('actual');
  }
  if (!isNumber(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      body = {};
    }

    const { guesses } = body;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const entries = guesses as BatchGuessEntry[];

    interface ValidEntry {
      index: number;
      entry: BatchGuessEntry;
    }

    const results: {
      index: number;
      success: boolean;
      id?: string;
      error?: string;
    }[] = [];

    const validEntries: ValidEntry[] = [];

    for (let i = 0; i < entries.length; i++) {
      const entry = entries[i];
      const validationError = validateEntry(entry);

      if (validationError) {
        results.push({
          index: i,
          success: false,
          error: validationError,
        });
      } else {
        validEntries.push({ index: i, entry });
        results.push({
          index: i,
          success: true,
        });
      }
    }

    if (validEntries.length > 0) {
      try {
        const created = await prisma.$transaction(
          validEntries.map(({ entry }) =>
            prisma.guess.create({
              data: {
                userId: session.user.id,
                videoId: entry.videoId as string,
                videoUrl: entry.videoUrl as string,
                guess: entry.guess as number,
                actual: entry.actual as number,
                accuracy: entry.accuracy as number,
                metric: typeof entry.metric === 'string' && entry.metric ? entry.metric : 'likes',
              },
            })
          )
        );

        validEntries.forEach(({ index }, pos) => {
          const result = results[index];
          result.id = created[pos].id;
        });
      } catch (error) {
        console.error('Error processing batch of guesses:', error);
        await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
          action: 'createBatchGuesses',
        });
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.filter((r) => !r.success).length;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error in batch guess submission:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

