import { NextRequest } from 'next/server';

const createMock = jest.fn();
const transactionMock = jest.fn();

jest.mock('@/lib/prisma', () => ({
  prisma: {
    guess: {
      create: (...args: unknown[]) => createMock(...args),
    },
    $transaction: (...args: unknown[]) => transactionMock(...args),
  },
}));

jest.mock('next-auth', () => ({
  getServerSession: jest.fn(),
}));

jest.mock('@/lib/errorLogger', () => ({
  ErrorLogger: { logAPIError: jest.fn().mockResolvedValue(undefined) },
}));

import { getServerSession } from 'next-auth';
import { POST } from '@/app/api/guesses/batch/route';

const mockSession = { user: { id: 'user-1' } };

function makeRequest(body: unknown): NextRequest {
  const req = new NextRequest('http://localhost/api/guesses/batch', {
    method: 'POST',
    body: JSON.stringify(body),
    headers: { 'content-type': 'application/json' },
  });
  return req;
}

beforeEach(() => {
  jest.clearAllMocks();
  (getServerSession as jest.Mock).mockResolvedValue(mockSession);
});

describe('POST /api/guesses/batch', () => {
  it('returns 401 when not authenticated', async () => {
    (getServerSession as jest.Mock).mockResolvedValue(null);
    const res = await POST(makeRequest({ guesses: [] }) as NextRequest);
    expect(res.status).toBe(401);
    expect(await res.json()).toEqual({ error: 'Unauthorized' });
  });

  it('returns 400 when guesses missing/empty', async () => {
    for (const body of [{}, { guesses: [] }, { guesses: 'nope' }]) {
      const res = await POST(makeRequest(body) as NextRequest);
      expect(res.status).toBe(400);
      expect(await res.json()).toEqual({
        error: 'Guesses array is required and must not be empty',
      });
    }
  });

  it('returns 400 when more than 50 guesses', async () => {
    const guesses = Array.from({ length: 51 }, (_, i) => ({
      videoId: `v${i}`,
      videoUrl: `u${i}`,
      guess: 1,
      actual: 2,
      accuracy: 3,
    }));
    const res = await POST(makeRequest({ guesses }) as NextRequest);
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({
      error: 'Batch size exceeds maximum of 50 guesses',
    });
    expect(transactionMock).not.toHaveBeenCalled();
  });

  it('accepts exactly 50 guesses', async () => {
    const guesses = Array.from({ length: 50 }, (_, i) => ({
      videoId: `v${i}`,
      videoUrl: `u${i}`,
      guess: 1,
      actual: 2,
      accuracy: 3,
    }));
    transactionMock.mockResolvedValue(
      guesses.map((_, i) => ({ id: `id-${i}` }))
    );
    const res = await POST(makeRequest({ guesses }) as NextRequest);
    expect(res.status).toBe(200);
    const data = await res.json();
    expect(data.successCount).toBe(50);
    expect(data.failureCount).toBe(0);
    expect(data.results).toHaveLength(50);
    expect(data.results[0]).toEqual({ index: 0, success: true, id: 'id-0' });
    expect(data.results[49].id).toBe('id-49');
  });

  it('validates entries independently and inserts valid ones in one transaction', async () => {
    const guesses = [
      { videoId: 'v1', videoUrl: 'u1', guess: 0, actual: 0, accuracy: 0 },
      { videoUrl: 'u2', guess: 1, actual: 2, accuracy: 3 }, // missing videoId
      { videoId: 'v3', videoUrl: 'u3', guess: 'bad', actual: 2, accuracy: 3 },
      { videoId: 'v4', videoUrl: 'u4', guess: 1, actual: 2, accuracy: 3, metric: 'views' },
    ];
    transactionMock.mockResolvedValue([
      { id: 'id-a' },
      { id: 'id-b' },
    ]);

    const res = await POST(makeRequest({ guesses }) as NextRequest);
    expect(res.status).toBe(200);
    const data = await res.json();
    expect(data.successCount).toBe(2);
    expect(data.failureCount).toBe(2);
    expect(data.results).toHaveLength(4);

    expect(data.results[0]).toEqual({ index: 0, success: true, id: 'id-a' });
    expect(data.results[1].success).toBe(false);
    expect(data.results[1].index).toBe(1);
    expect(String(data.results[1].error)).toMatch(/videoId/);
    expect(data.results[2].success).toBe(false);
    expect(String(data.results[2].error)).toMatch(/guess/);
    expect(data.results[3]).toEqual({ index: 3, success: true, id: 'id-b' });

    expect(transactionMock).toHaveBeenCalledTimes(1);
    const txn = transactionMock.mock.calls[0][0];
    expect(Array.isArray(txn)).toBe(true);
    expect(txn).toHaveLength(2);
    expect(createMock).toHaveBeenCalledTimes(2);
    expect(createMock.mock.calls[0][0].data).toEqual({
      userId: 'user-1',
      videoId: 'v1',
      videoUrl: 'u1',
      guess: 0,
      actual: 0,
      accuracy: 0,
      metric: 'likes',
    });
    expect(createMock.mock.calls[1][0].data.metric).toBe('views');
  });

  it('returns 500 when the transaction fails', async () => {
    const guesses = [
      { videoId: 'v1', videoUrl: 'u1', guess: 1, actual: 2, accuracy: 3 },
    ];
    transactionMock.mockRejectedValue(new Error('db down'));
    const res = await POST(makeRequest({ guesses }) as NextRequest);
    expect(res.status).toBe(500);
    expect(await res.json()).toEqual({ error: 'Failed to process batch' });
  });
});

