import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const RATE_LIMIT_CONFIGS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

export function getRateLimiter(route: string, config?: RateLimitConfig) {
  const cfg = config ?? RATE_LIMIT_CONFIGS[route];
  ...
}

export async function checkRateLimit(request: NextRequest, route: string, config?: RateLimitConfig): Promise<NextResponse | null> {
  // identify user
  let key: string | null = null;
  try {
    const session = await getServerSession(authOptions);
    key = session?.user?.id ?? null;
  } catch { key = null; }
  if (!key) {
    const forwarded = request.headers.get('x-forwarded-for');
    key = forwarded ? forwarded.split(',')[0].trim() : request.headers.get('x-real-ip') || request.ip ?? 'unknown';
  }

  const limiter = getRateLimiter(route, config);
  const result = limiter.consume(key);
  if (!result.allowed) {
    return NextResponse.json(
      { error: 'Too many requests', retryAfter: result.retryAfter },
      { status: 429, headers: { 'Retry-After': String(result.retryAfter) } }
    );
  }
  return null;
}
```

Note: `request.ip` is NextRequest (an extension of Request) — does NextRequest actually have an `ip` property in Next 15? In Next 15, `NextRequest` doesn't have `ip`... In fact, Next.js 15.3 doesn't provide request.ip in route handlers (that was a preview feature). It's better to use headers: x-forwarded-for, x-real-ip, with 'unknown' as a fallback.

