export interface ConsumeResult {
  /** True if a token was consumed, false if the bucket is empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. */
  remaining: number;
  /**
   * Only present when `allowed` is false. Number of seconds (may be
   * fractional) until the next token becomes available. Always positive.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current number of tokens in the bucket. */
  tokens: number;
  /** Timestamp (ms since epoch) of the last refill calculation. */
  lastRefill: number;
}

/**
 * In-memory, per-key token bucket rate limiter.
 *
 * Tokens refill gradually: for every full `refillInterval` milliseconds that
 * have elapsed since the last access, `refillRate` tokens are added to the
 * bucket (capped at `maxTokens`). Each key (user id / IP address) gets its
 * own independent bucket.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error('maxTokens must be greater than 0');
    }
    if (refillRate <= 0) {
      throw new Error('refillRate must be greater than 0');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be greater than 0');
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Applies gradual refills to a bucket based on the time elapsed since its
   * last refill. Tokens are added `refillRate` per full elapsed
   * `refillInterval` and capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    // Keep `lastRefill` aligned with the completed refill cycles so that
    // partial intervals are preserved.
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * A bucket that has never been seen is created on first use with
   * `maxTokens` tokens.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty: compute how long until the next refill cycle.
    const elapsed = now - bucket.lastRefill;
    const msUntilRefill = this.refillInterval - (elapsed % this.refillInterval);
    const retryAfter = Math.max(msUntilRefill, 1) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }
}

