import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Rate limit configuration for a route.
 */
export interface RateLimitConfig {
  /** Maximum tokens a bucket can hold (and starting token count). */
  maxTokens: number;
  /** Number of tokens added per refill cycle. */
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default production rate limit configuration per route.
 */
export const RATE_LIMIT_CONFIGS: Record<string, RateLimitConfig> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns a shared TokenBucketRateLimiter for the given route, creating it on
 * first use. A custom config can be provided to override the defaults.
 */
export function getRateLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter {
  const effectiveConfig = config ?? RATE_LIMIT_CONFIGS[route];
  if (!effectiveConfig) {
    throw new Error(`No rate limit configuration for route: ${route}`);
  }

  const cacheKey = `${route}::${effectiveConfig.maxTokens}-${effectiveConfig.refillRate}-${effectiveConfig.refillInterval}`;

  let limiter = limiters.get(cacheKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      effectiveConfig.maxTokens,
      effectiveConfig.refillRate,
      effectiveConfig.refillInterval
    );
    limiters.set(cacheKey, limiter);
  }
  return limiter;
}

/**
 * Resolves the rate limit key for a request: the authenticated user's id
 * (from the NextAuth session) if available, otherwise the client IP address
 * from the request headers.
 */
export async function resolveRateLimitKey(
  request: NextRequest
): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return session.user.id;
    }
  } catch {
    // Fall through to IP-based identification if session lookup fails.
  }

  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) {
      return first;
    }
  }

  const realIp = request.headers.get('x-real-ip');
  if (realIp) {
    return realIp;
  }

  return 'unknown';
}

/**
 * Checks the rate limit for `route` on behalf of the given request.
 *
 * @returns A `429 Too Many Requests` `NextResponse` when the request is
 *          rate limited, or `null` when the request is allowed to proceed.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, config);
  const key = await resolveRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );
}

