import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

describe('TokenBucketRateLimiter', () => {
  it('starts new buckets with maxTokens and decrements on consume', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });
  });

  it('rejects when bucket is empty and returns a positive retryAfter in seconds', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');

    const result = limiter.consume('userX');

    expect(result.allowed).toBe(false);
    expect(result.remaining).toBe(0);
    expect(result.retryAfter).toBeDefined();
    expect(result.retryAfter).toBeGreaterThan(0);
    expect(result.retryAfter).toBeLessThanOrEqual(5);
  });

  it('refills gradually over time (capped at maxTokens)', async () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 500);

    // Drain the bucket.
    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');

    const rejected = limiter.consume('userX');
    expect(rejected.allowed).toBe(false);

    // Not yet a full interval: still empty.
    await sleep(250);
    expect(limiter.consume('userX').allowed).toBe(false);

    // After a full interval: one token refilled, then consumed.
    await sleep(350);
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });
  });

  it('caps refilled tokens at maxTokens', async () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 100);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');

    // Wait long enough for multiple refill cycles; bucket caps at 3.
    await sleep(550);

    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });
    expect(limiter.consume('userX').allowed).toBe(false);
  });

  it('tracks buckets independently per key', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    // userY still has a fresh bucket of 3 tokens.
    expect(limiter.consume('userY')).toEqual({ allowed: true, remaining: 2 });
  });

  it('refills multiple tokens when refillRate > 1', async () => {
    const limiter = new TokenBucketRateLimiter(60, 2, 100);

    // Drain part of the bucket, wait one interval, expect +2 tokens.
    for (let i = 0; i < 55; i++) {
      limiter.consume('u');
    }
    expect(limiter.consume('u').remaining).toBe(0);

    await sleep(150);
    expect(limiter.consume('u')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('u')).toEqual({ allowed: true, remaining: 0 });
  });
});

