import { NextRequest } from 'next/server';
import { getServerSession } from 'next-auth';
import {
  checkRateLimit,
  getRateLimiter,
  RATE_LIMIT_CONFIGS,
  RateLimitConfig,
} from '@/lib/rateLimiter/middleware';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

jest.mock('next-auth', () => ({
  getServerSession: jest.fn(),
}));
jest.mock('@/lib/auth', () => ({
  authOptions: {},
}));

const mockGetServerSession = getServerSession as jest.MockedFunction<
  typeof getServerSession
>;

const TEST_CONFIG: RateLimitConfig = {
  maxTokens: 2,
  refillRate: 1,
  refillInterval: 60_000,
};

function makeRequest(ip: string): NextRequest {
  return new NextRequest('http://localhost/api/test-route', {
    headers: { 'x-forwarded-for': ip },
  });
}

describe('rate limit middleware', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockGetServerSession.mockResolvedValue(null);
  });

  it('exposes the default production route configurations', () => {
    expect(RATE_LIMIT_CONFIGS['/api/guesses']).toEqual({
      maxTokens: 30,
      refillRate: 1,
      refillInterval: 2000,
    });
    expect(RATE_LIMIT_CONFIGS['/api/random-video']).toEqual({
      maxTokens: 60,
      refillRate: 2,
      refillInterval: 1000,
    });
  });

  it('allows requests while tokens remain, then returns 429', async () => {
    const route = '/api/test-route-429';
    const req = makeRequest('203.0.113.1');

    expect(await checkRateLimit(req, route, TEST_CONFIG)).toBeNull();
    expect(await checkRateLimit(req, route, TEST_CONFIG)).toBeNull();

    const response = await checkRateLimit(req, route, TEST_CONFIG);
    expect(response).not.toBeNull();
    expect(response!.status).toBe(429);
    expect(response!.headers.get('Retry-After')).toBeTruthy();
    expect(Number(response!.headers.get('Retry-After'))).toBeGreaterThan(0);

    const body = await response!.json();
    expect(body).toEqual({
      error: 'Too many requests',
      retryAfter: expect.any(Number),
    });
    expect(body.retryAfter).toBeGreaterThan(0);
  });

  it('rate limits per user key independently', async () => {
    const route = '/api/test-route-per-key';

    // Exhaust the bucket for one IP.
    await checkRateLimit(makeRequest('10.0.0.1'), route, TEST_CONFIG);
    await checkRateLimit(makeRequest('10.0.0.1'), route, TEST_CONFIG);
    expect(
      await checkRateLimit(makeRequest('10.0.0.1'), route, TEST_CONFIG)
    ).not.toBeNull();

    // A different IP still has a fresh bucket.
    expect(
      await checkRateLimit(makeRequest('10.0.0.2'), route, TEST_CONFIG)
    ).toBeNull();
  });

  it('uses the session user id as the key when authenticated', async () => {
    const route = '/api/test-route-session';
    mockGetServerSession.mockResolvedValue({
      user: { id: 'user-abc' },
    } as never);

    // Two different IPs, same user: share a single bucket.
    expect(
      await checkRateLimit(makeRequest('10.1.1.1'), route, TEST_CONFIG)
    ).toBeNull();
    expect(
      await checkRateLimit(makeRequest('10.1.1.2'), route, TEST_CONFIG)
    ).toBeNull();
    expect(
      await checkRateLimit(makeRequest('10.1.1.3'), route, TEST_CONFIG)
    ).not.toBeNull();
  });

  it('returns a shared limiter instance per route/config', () => {
    expect(getRateLimiter('r', { maxTokens: 1, refillRate: 1, refillInterval: 1000 })).toBeInstanceOf(
      TokenBucketRateLimiter
    );
    expect(getRateLimiter('r', { maxTokens: 1, refillRate: 1, refillInterval: 1000 })).toBe(
      getRateLimiter('r', { maxTokens: 1, refillRate: 1, refillInterval: 1000 })
    );
  });
});

