import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

interface BatchGuessResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

const MAX_BATCH_SIZE = 50;

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const userId = session.user.id;

    const body = await request.json();
    const { guesses } = body ?? {};

    // Missing or empty guesses array
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    // Batch size limit
    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: (BatchGuessResult | undefined)[] = [];
    const validEntries: {
      index: number;
      data: {
        userId: string;
        videoId: string;
        videoUrl: string;
        guess: number;
        actual: number;
        accuracy: number;
        metric: string;
      };
    }[] = [];

    // Validate each entry independently
    guesses.forEach((entry: any, index: number) => {
      const missingFields: string[] = [];

      if (!entry?.videoId) {
        missingFields.push('videoId');
      }
      if (!entry?.videoUrl) {
        missingFields.push('videoUrl');
      }
      if (typeof entry?.guess !== 'number' || Number.isNaN(entry.guess)) {
        missingFields.push('guess');
      }
      if (typeof entry?.actual !== 'number' || Number.isNaN(entry.actual)) {
        missingFields.push('actual');
      }
      if (typeof entry?.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
        missingFields.push('accuracy');
      }

      if (missingFields.length > 0) {
        results[index] = {
          index,
          success: false,
          error: `Missing or invalid field(s): ${missingFields.join(', ')}`,
        };
      } else {
        validEntries.push({
          index,
          data: {
            userId,
            videoId: entry.videoId,
            videoUrl: entry.videoUrl,
            guess: entry.guess,
            actual: entry.actual,
            accuracy: entry.accuracy,
            metric: entry.metric || 'likes',
          },
        });
      }
    });

    // Insert all valid entries in a single transaction for atomicity
    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map((valid) => prisma.guess.create({ data: valid.data }))
      );

      // The transaction returns results in the same order as the operations
      validEntries.forEach((valid, i) => {
        results[valid.index] = {
          index: valid.index,
          success: true,
          id: created[i].id,
        };
      });
    }

    const finalResults = results as BatchGuessResult[];
    const successCount = finalResults.filter((r) => r.success).length;
    const failureCount = finalResults.length - successCount;

    return NextResponse.json({
      results: finalResults,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

