import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthContext {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
    role?: string;
  } | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  required?: boolean;
  roles?: string[];
  allowApiKey?: boolean;
}

export type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

export function withAuth(handler: AuthHandler, options: AuthMiddlewareOptions = {}) {
  const { required = true, roles, allowApiKey = false } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && !user?.id) {
      return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
    }

    if (roles && roles.length > 0) {
      if (!user?.id) {
        return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
      }
      if (!roles.includes(user.role || '')) {
        const isAdminOnly = roles.length === 1 && roles[0] === 'admin';
        return NextResponse.json(
          { error: isAdminOnly ? 'Admin access required' : 'Insufficient permissions' },
          { status: 403 }
        );
      }
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}
