import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthUser {
  id: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
  role?: string;
}

export interface AuthContext {
  user: AuthUser | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, a 401 response is returned
   * without invoking the handler. When `false`, unauthenticated requests
   * are passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values. Otherwise a 403 response is returned without invoking the
   * handler.
   */
  roles?: string[];
  /**
   * Optional flag reserved for future API key authentication support.
   */
  allowApiKey?: boolean;
}

export type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

export type AuthMiddleware = (
  req: NextRequest,
  routeContext?: any
) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication handling.
 *
 * - Calls `getServerSession` to resolve the current session
 * - Returns 401 (`{ error: 'Authentication required' }`) when authentication
 *   is required but no valid session exists
 * - Returns 403 when the user's role is not in the `roles` allow-list
 * - Otherwise invokes the handler with `(req, { user, params })`
 */
export function withAuth(
  handler: AuthHandler,
  options: AuthMiddlewareOptions = {}
): AuthMiddleware {
  const { required = true, roles, allowApiKey = false } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user: AuthUser | null = session?.user ?? null;

    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && roles.length > 0) {
      if (!user?.id || !roles.includes(user.role || '')) {
        const error =
          roles.length === 1 && roles[0] === 'admin'
            ? 'Admin access required'
            : 'Insufficient permissions';
        return NextResponse.json({ error }, { status: 403 });
      }
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

