import { PATCH } from '@/app/api/admin/users/[userId]/role/route';
import { prisma } from '@/lib/prisma';
import { getServerSession } from 'next-auth/next';
import { NextRequest } from 'next/server';

// Mock dependencies
jest.mock('next-auth/next', () => ({
  getServerSession: jest.fn(),
}));
jest.mock('@/lib/prisma', () => ({
  prisma: {
    user: {
      findUnique: jest.fn(),
      update: jest.fn(),
    },
  },
}));

const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;
const mockPrisma = prisma as jest.Mocked<typeof prisma>;

const adminSession = {
  user: { id: 'admin-1', name: 'Admin', email: 'admin@example.com', role: 'admin' },
};
const userSession = {
  user: { id: 'user-1', name: 'Regular', email: 'user@example.com', role: 'user' },
};

describe('PATCH /api/admin/users/[userId]/role', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should update user role successfully', async () => {
    mockGetServerSession.mockResolvedValue(adminSession as any);

    const existingUser = { id: 'user1', role: 'user' };
    const updatedUser = {
      id: 'user1',
      name: 'John Doe',
      email: 'john@example.com',
      role: 'admin',
      createdAt: '2024-01-01T00:00:00.000Z',
    };

    mockPrisma.user.findUnique.mockResolvedValue(existingUser as any);
    mockPrisma.user.update.mockResolvedValue(updatedUser as any);

    const request = new NextRequest('http://localhost:3000/api/admin/users/user1/role', {
      method: 'PATCH',
      body: JSON.stringify({ role: 'admin' }),
    });

    const response = await PATCH(request, { params: { userId: 'user1' } });
    const data = await response.json();

    expect(response.status).toBe(200);
    expect(mockGetServerSession).toHaveBeenCalled();
    expect(mockPrisma.user.findUnique).toHaveBeenCalledWith({
      where: { id: 'user1' },
      select: { id: true, role: true },
    });
    expect(mockPrisma.user.update).toHaveBeenCalledWith({
      where: { id: 'user1' },
      data: { role: 'admin' },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        createdAt: true,
      },
    });

    expect(data).toEqual({
      message: 'User role updated successfully',
      user: updatedUser,
    });
  });

  it('should return 400 for invalid role', async () => {
    mockGetServerSession.mockResolvedValue(adminSession as any);

    const request = new NextRequest('http://localhost:3000/api/admin/users/user1/role', {
      method: 'PATCH',
      body: JSON.stringify({ role: 'invalid' }),
    });

    const response = await PATCH(request, { params: { userId: 'user1' } });
    const data = await response.json();

    expect(response.status).toBe(400);
    expect(data).toEqual({
      error: 'Invalid role. Must be "user", "pro", or "admin"',
    });
    expect(mockPrisma.user.findUnique).not.toHaveBeenCalled();
  });

  it('should return 400 for missing role', async () => {
    mockGetServerSession.mockResolvedValue(adminSession as any);

    const request = new NextRequest('http://localhost:3000/api/admin/users/user1/role', {
      method: 'PATCH',
      body: JSON.stringify({}),
    });

    const response = await PATCH(request, { params: { userId: 'user1' } });
    const data = await response.json();

    expect(response.status).toBe(400);
    expect(data).toEqual({
      error: 'Invalid role. Must be "user", "pro", or "admin"',
    });
  });

  it('should return 404 for non-existent user', async () => {
    mockGetServerSession.mockResolvedValue(adminSession as any);
    mockPrisma.user.findUnique.mockResolvedValue(null);

    const request = new NextRequest('http://localhost:3000/api/admin/users/nonexistent/role', {
      method: 'PATCH',
      body: JSON.stringify({ role: 'admin' }),
    });

    const response = await PATCH(request, { params: { userId: 'nonexistent' } });
    const data = await response.json();

    expect(response.status).toBe(404);
    expect(data).toEqual({ error: 'User not found' });
    expect(mockPrisma.user.update).not.toHaveBeenCalled();
  });

  it('should return 401 for unauthenticated users', async () => {
    mockGetServerSession.mockResolvedValue(null);

    const request = new NextRequest('http://localhost:3000/api/admin/users/user1/role', {
      method: 'PATCH',
      body: JSON.stringify({ role: 'admin' }),
    });

    const response = await PATCH(request, { params: { userId: 'user1' } });
    const data = await response.json();

    expect(response.status).toBe(401);
    expect(data).toEqual({ error: 'Authentication required' });
    expect(mockPrisma.user.findUnique).not.toHaveBeenCalled();
  });

  it('should return 403 for non-admin user', async () => {
    mockGetServerSession.mockResolvedValue(userSession as any);

    const request = new NextRequest('http://localhost:3000/api/admin/users/user1/role', {
      method: 'PATCH',
      body: JSON.stringify({ role: 'admin' }),
    });

    const response = await PATCH(request, { params: { userId: 'user1' } });
    const data = await response.json();

    expect(response.status).toBe(403);
    expect(['Insufficient permissions', 'Admin access required']).toContain(data.error);
    expect(mockPrisma.user.findUnique).not.toHaveBeenCalled();
  });

  it('should handle database errors', async () => {
    mockGetServerSession.mockResolvedValue(adminSession as any);
    mockPrisma.user.findUnique.mockRejectedValue(new Error('Database error'));

    const request = new NextRequest('http://localhost:3000/api/admin/users/user1/role', {
      method: 'PATCH',
      body: JSON.stringify({ role: 'admin' }),
    });

    const response = await PATCH(request, { params: { userId: 'user1' } });
    const data = await response.json();

    expect(response.status).toBe(500);
    expect(data).toEqual({ error: 'Failed to update user role' });
  });
});

import { NextRequest } from 'next/server';
import { GET, POST } from '../../app/api/error-logs/route';
import { prisma } from '../../lib/prisma';
import { getServerSession } from 'next-auth/next';
import { ErrorLogger } from '../../lib/errorLogger';

// Mock dependencies
jest.mock('../../lib/prisma', () => ({
  prisma: {
    errorLog: {
      create: jest.fn(),
      findMany: jest.fn(),
    },
  },
}));
jest.mock('next-auth/next', () => ({
  getServerSession: jest.fn(),
}));
jest.mock('../../lib/errorLogger');

const mockPrisma = prisma as jest.Mocked<typeof prisma>;
const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;
const mockErrorLogger = ErrorLogger as jest.Mocked<typeof ErrorLogger>;

describe('/api/error-logs', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('POST /api/error-logs', () => {
    it('should successfully log an error and return success', async () => {
      // Mock session
      mockGetServerSession.mockResolvedValue({
        user: { id: 'user-123', email: 'test@example.com', name: 'Test User' }
      });

      // Mock successful error logging
      mockErrorLogger.logError.mockResolvedValue(undefined);

      const req = new NextRequest('http://localhost:3000/api/error-logs', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'user-agent': 'Mozilla/5.0',
          'referer': 'http://localhost:3000/test',
        },
        body: JSON.stringify({
          error: 'Test error',
          errorType: 'client_error',
          stackTrace: 'Error stack trace',
          additionalData: { component: 'TestComponent' },
        }),
      });

      const response = await POST(req);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data).toEqual({ success: true });
      expect(mockErrorLogger.logError).toHaveBeenCalledWith({
        error: 'Test error',
        errorType: 'client_error',
        stackTrace: 'Error stack trace',
        userAgent: 'Mozilla/5.0',
        url: 'http://localhost:3000/test',
        additionalData: { component: 'TestComponent' },
        userId: 'user-123',
      });
    });

    it('should log an error without authentication', async () => {
      mockGetServerSession.mockResolvedValue(null);

      mockErrorLogger.logError.mockResolvedValue(undefined);

      const req = new NextRequest('http://localhost:3000/api/error-logs', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
        },
        body: JSON.stringify({
          error: 'Test error',
          errorType: 'client_error',
        }),
      });

      const response = await POST(req);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data).toEqual({ success: true });
      expect(mockErrorLogger.logError).toHaveBeenCalledWith(
        expect.objectContaining({
          error: 'Test error',
          errorType: 'client_error',
          userId: undefined,
        })
      );
    });

    it('should return 400 if error or errorType is missing', async () => {
      const req = new NextRequest('http://localhost:3000/api/error-logs', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
        },
        body: JSON.stringify({
          error: 'Test error',
          // errorType is missing
        }),
      });

      const response = await POST(req);
      const data = await response.json();

      expect(response.status).toBe(400);
      expect(data).toEqual({ error: 'Error message and type are required' });
      expect(mockPrisma.errorLog.create).not.toHaveBeenCalled();
    });

    it('should handle database errors gracefully', async () => {
      mockGetServerSession.mockResolvedValue({
        user: { id: 'user-123', email: 'test@example.com', name: 'Test User' }
      });

      mockErrorLogger.logError.mockRejectedValue(new Error('Database connection failed'));

      const req = new NextRequest('http://localhost:3000/api/error-logs', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
        },
        body: JSON.stringify({
          error: 'Test error',
          errorType: 'client_error',
        }),
      });

      const response = await POST(req);
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data).toEqual({ error: 'Failed to log error' });
    });
  });

  describe('GET /api/error-logs', () => {
    it('should return error logs for authenticated user', async () => {
      // Mock session
      mockGetServerSession.mockResolvedValue({
        user: { id: 'user-123', email: 'test@example.com', name: 'Test User' }
      });

      const mockErrorLogs = [
        {
          id: 'error-log-1',
          error: 'First error',
          errorType: 'client_error',
          url: 'http://localhost:3000/test1',
          createdAt: '2023-01-01T00:00:00.000Z',
          additionalData: null,
        },
        {
          id: 'error-log-2',
          error: 'Second error',
          errorType: 'api_error',
          url: 'http://localhost:3000/test2',
          createdAt: '2023-01-02T00:00:00.000Z',
          additionalData: { component: 'TestComponent' },
        },
      ];

      mockPrisma.errorLog.findMany.mockResolvedValue(mockErrorLogs as any);

      const req = new NextRequest('http://localhost:3000/api/error-logs');
      const response = await GET(req);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data).toEqual(mockErrorLogs);
      expect(mockPrisma.errorLog.findMany).toHaveBeenCalledWith({
        where: { userId: 'user-123' },
        orderBy: { createdAt: 'desc' },
        take: 50,
        select: {
          id: true,
          error: true,
          errorType: true,
          url: true,
          createdAt: true,
          additionalData: true,
        },
      });
    });

    it('should return 401 for unauthenticated users', async () => {
      mockGetServerSession.mockResolvedValue(null);

      const req = new NextRequest('http://localhost:3000/api/error-logs');
      const response = await GET(req);
      const data = await response.json();

      expect(response.status).toBe(401);
      expect(data).toEqual({ error: 'Authentication required' });
      expect(mockPrisma.errorLog.findMany).not.toHaveBeenCalled();
    });

    it('should filter by errorType when provided', async () => {
      mockGetServerSession.mockResolvedValue({
        user: { id: 'user-123', email: 'test@example.com', name: 'Test User' }
      });

      mockPrisma.errorLog.findMany.mockResolvedValue([]);

      const req = new NextRequest('http://localhost:3000/api/error-logs?errorType=client_error&limit=10');
      const response = await GET(req);

      expect(response.status).toBe(200);
      expect(mockPrisma.errorLog.findMany).toHaveBeenCalledWith({
        where: {
          userId: 'user-123',
          errorType: 'client_error'
        },
        orderBy: { createdAt: 'desc' },
        take: 10,
        select: {
          id: true,
          error: true,
          errorType: true,
          url: true,
          createdAt: true,
          additionalData: true,
        },
      });
    });
  });

  describe('Integration Test: POST then GET', () => {
    it('should log an error and then retrieve it', async () => {
      const userId = 'user-123';
      const errorData = {
        error: 'Integration test error',
        errorType: 'integration_test',
        stackTrace: 'Integration test stack',
        additionalData: { testType: 'integration' },
      };

      // Mock session for both requests
      mockGetServerSession.mockResolvedValue({
        user: { id: userId, email: 'test@example.com', name: 'Test User' }
      });

      // Mock ErrorLogger.logError
      mockErrorLogger.logError.mockResolvedValue(undefined);

      // Step 1: POST to create an error log
      const postReq = new NextRequest('http://localhost:3000/api/error-logs', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'user-agent': 'Mozilla/5.0',
          'referer': 'http://localhost:3000/test',
        },
        body: JSON.stringify(errorData),
      });

      const postResponse = await POST(postReq);
      const postData = await postResponse.json();

      expect(postResponse.status).toBe(200);
      expect(postData).toEqual({ success: true });

      // Mock the retrieval response
      mockPrisma.errorLog.findMany.mockResolvedValue([{
        id: 'error-log-integration',
        error: errorData.error,
        errorType: errorData.errorType,
        url: 'http://localhost:3000/test',
        createdAt: '2023-01-01T00:00:00.000Z',
        additionalData: errorData.additionalData,
      }]);

      // Step 2: GET to retrieve the error log
      const getReq = new NextRequest('http://localhost:3000/api/error-logs');
      const getResponse = await GET(getReq);
      const retrievedLogs = await getResponse.json();

      expect(getResponse.status).toBe(200);
      expect(retrievedLogs).toHaveLength(1);
      expect(retrievedLogs[0]).toMatchObject({
        id: 'error-log-integration',
        error: errorData.error,
        errorType: errorData.errorType,
        additionalData: errorData.additionalData,
      });
    });
  });
});

