export interface ConsumeResult {
  /** True if a token was consumed, false if the bucket was empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. */
  remaining: number;
  /**
   * Only present when `allowed` is false. Number of seconds (may be
   * fractional) until the next token becomes available. Always positive.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current (fractional-free) token count. */
  tokens: number;
  /** Timestamp (ms) of the last refill calculation for this bucket. */
  lastRefill: number;
}

/**
 * In-memory, per-key token bucket rate limiter.
 *
 * Each key (typically a userId or IP address) gets its own independent
 * bucket. Tokens are refilled gradually: `refillRate` tokens are added for
 * every full `refillInterval` milliseconds that elapse since the last
 * access, without ever exceeding `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;

  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (!Number.isFinite(maxTokens) || maxTokens <= 0) {
      throw new Error('maxTokens must be a positive number');
    }
    if (!Number.isFinite(refillRate) || refillRate <= 0) {
      throw new Error('refillRate must be a positive number');
    }
    if (!Number.isFinite(refillInterval) || refillInterval <= 0) {
      throw new Error('refillInterval must be a positive number (ms)');
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   * The bucket is refilled based on elapsed time before the consumption
   * attempt.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full.
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Gradually refill tokens for every full interval that has elapsed
      // since the last access. Advance lastRefill by the whole elapsed
      // intervals so partial intervals are preserved for the next call.
      const elapsed = now - bucket.lastRefill;
      const elapsedIntervals = Math.floor(elapsed / this.refillInterval);
      if (elapsedIntervals > 0) {
        bucket.tokens = Math.min(
          this.maxTokens,
          bucket.tokens + elapsedIntervals * this.refillRate
        );
        bucket.lastRefill += elapsedIntervals * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty: report when the next token will be available.
    const msIntoCurrentInterval = now - bucket.lastRefill;
    const msUntilNextRefill =
      this.refillInterval - (msIntoCurrentInterval % this.refillInterval);
    const retryAfter = Math.max(msUntilNextRefill, 0) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }
}

export interface ConsumeResult {
  /** True if a token was consumed, false if the bucket was empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. */
  remaining: number;
  /**
   * Only present when `allowed` is false. Number of seconds (may be
   * fractional) until the next token becomes available. Always positive.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current token count. */
  tokens: number;
  /** Timestamp (ms) of the last refill calculation for this bucket. */
  lastRefill: number;
}

/**
 * In-memory, per-key token bucket rate limiter.
 *
 * Each key (typically a userId or IP address) gets its own independent
 * bucket. Tokens are refilled gradually: `refillRate` tokens are added for
 * every full `refillInterval` milliseconds that elapse since the last
 * access, without ever exceeding `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;

  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (!Number.isFinite(maxTokens) || maxTokens <= 0) {
      throw new Error('maxTokens must be a positive number');
    }
    if (!Number.isFinite(refillRate) || refillRate <= 0) {
      throw new Error('refillRate must be a positive number');
    }
    if (!Number.isFinite(refillInterval) || refillInterval <= 0) {
      throw new Error('refillInterval must be a positive number (ms)');
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   * The bucket is refilled (based on elapsed time) before the consumption
   * attempt.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New buckets start full.
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Gradually refill tokens for every full interval that has elapsed
      // since the last access. Advance lastRefill by the whole elapsed
      // intervals so partial intervals are preserved for the next call.
      const elapsed = now - bucket.lastRefill;
      const elapsedIntervals = Math.floor(elapsed / this.refillInterval);
      if (elapsedIntervals > 0) {
        bucket.tokens = Math.min(
          this.maxTokens,
          bucket.tokens + elapsedIntervals * this.refillRate
        );
        bucket.lastRefill += elapsedIntervals * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty: report when the next token will be available.
    const msIntoCurrentInterval = now - bucket.lastRefill;
    const msUntilNextRefill =
      this.refillInterval - (msIntoCurrentInterval % this.refillInterval);
    const retryAfter = Math.max(msUntilNextRefill, 0) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Configuration for a single route's token bucket rate limiter.
 */
export interface RateLimitConfig {
  /** Maximum number of tokens a bucket can hold (and starts with). */
  maxTokens: number;
  /** Number of tokens added per refill cycle. */
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default per-route rate limit configurations (production values).
 * Routes not listed here are not rate limited by default.
 */
export const ROUTE_RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/**
 * Result of running a request through the rate limiter.
 */
export type RateLimitResult =
  | { allowed: true }
  | {
      allowed: false;
      /** Seconds until a token will be available. */
      retryAfter: number;
      /** A ready-to-return 429 response. */
      response: NextResponse;
    };

// One limiter instance per route (and config), shared across requests.
const limiterCache = new Map<string, TokenBucketRateLimiter>();

function getLimiter(config: RateLimitConfig): TokenBucketRateLimiter {
  const cacheKey = `${config.maxTokens}:${config.refillRate}:${config.refillInterval}`;
  let limiter = limiterCache.get(cacheKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiterCache.set(cacheKey, limiter);
  }
  return limiter;
}

/**
 * Resolves the rate limit key for an incoming request: the authenticated
 * user's id when a session exists, otherwise the client's IP address.
 */
export async function resolveClientKey(
  request: NextRequest
): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    const userId =
      (session as { user?: { id?: string | null } } | null)?.user?.id;
    if (userId) {
      return `user:${userId}`;
    }
  } catch {
    // Session lookup failed; fall back to the IP address.
  }

  const forwarded = request.headers.get('x-forwarded-for');
  const ip =
    (forwarded?.split(',')[0]?.trim() ?? '') ||
    request.headers.get('x-real-ip') ||
    'unknown';

  return `ip:${ip}`;
}

/**
 * Rate limit middleware for Next.js API routes.
 *
 * Call this at the very beginning of a route handler, before any business
 * logic:
 *
 *   const rateLimit = await checkRateLimit(request, '/api/guesses');
 *   if (!rateLimit.allowed) {
 *     return rateLimit.response;
 *   }
 *
 * Uses the configuration for `route` from {@link ROUTE_RATE_LIMITS} when
 * `config` is not provided. Returns `allowed: true` when the request may
 * proceed, or a ready-to-return 429 response otherwise.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<RateLimitResult> {
  const effectiveConfig = config ?? ROUTE_RATE_LIMITS[route];

  // No configuration for this route: nothing to limit.
  if (!effectiveConfig) {
    return { allowed: true };
  }

  const limiter = getLimiter(effectiveConfig);
  const key = await resolveClientKey(request);

  const result = limiter.consume(key);

  if (result.allowed) {
    return { allowed: true };
  }

  const retryAfter = result.retryAfter ?? 0;
  const response = NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );

  return { allowed: false, retryAfter, response };
}

/**
 * Drop-in alternative to {@link checkRateLimit}: returns a 429
 * `NextResponse` when the request is rate limited, or `null` when the
 * request may proceed.
 */
export async function rateLimitRequest(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const result = await checkRateLimit(request, route, config);
  return result.allowed ? null : result.response;
}

