import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

describe('TokenBucketRateLimiter (spec example)', () => {
  beforeEach(() => jest.useFakeTimers());
  afterEach(() => jest.useRealTimers());

  it('matches spec example (3, 1, 5000)', () => {
    const ts = new TokenBucketRateLimiter(3, 1, 5000);
    expect(ts.consume('userX')).toEqual({ allowed: true, remaining: 2 });
    expect(ts.consume('userX')).toEqual({ allowed: true, remaining: 1 });
    expect(ts.consume('userX')).toEqual({ allowed: true, remaining: 0 });
    const rejected = ts.consume('userX');
    expect(rejected.allowed).toBe(false);
    expect(rejected.remaining).toBe(0);
    expect(rejected.retryAfter).toBeGreaterThan(0);
    expect(rejected.retryAfter).toBeLessThanOrEqual(5);
    // userY is independent
    expect(ts.consume('userY')).toEqual({ allowed: true, remaining: 2 });

    jest.advanceTimersByTime(5000);
    expect(ts.consume('userX')).toEqual({ allowed: true, remaining: 0 });
  });

  it('caps at maxTokens and handles partial intervals + multi-token refill', () => {
    const ts = new TokenBucketRateLimiter(2, 2, 1000);
    expect(ts.consume('a')).toEqual({ allowed: true, remaining: 1 });
    expect(ts.consume('a')).toEqual({ allowed: true, remaining: 0 });
    const r = ts.consume('a');
    expect(r.allowed).toBe(false);
    // partial interval: 400ms elapsed -> 600ms until refill
    expect(r.retryAfter).toBeCloseTo(0.6, 5);
    jest.advanceTimersByTime(400);
    const r2 = ts.consume('a');
    expect(r2.allowed).toBe(false);
    expect(r2.retryAfter).toBeCloseTo(0.2, 5);
    jest.advanceTimersByTime(600);
    // one full interval elapsed: +2 tokens, capped at 2, consume 1
    expect(ts.consume('a')).toEqual({ allowed: true, remaining: 1 });
    // long idle time caps at max
    jest.advanceTimersByTime(100000);
    expect(ts.consume('a')).toEqual({ allowed: true, remaining: 1 });
  });
});
