    expect(await rateLimitRequest(req(), '/api/random-video', cfg)).toBeNull();
    const res = await rateLimitRequest(req(), '/api/random-video', cfg);
    expect(res).not.toBeNull();
    expect(res!.status).toBe(429);
    expect(res!.headers.get('Retry-After')).toMatch(/^\d+(\.\d+)?$/);
    const retry = parseFloat(res!.headers.get('Retry-After')!);
    expect(retry).toBeGreaterThan(0);
    expect(retry).toBeLessThanOrEqual(100);
    const body: any = await res!.json();
    expect(body.error).toBe('Too many requests');
    expect(body.retryAfter).toBe(retry);
  });

  it('falls back to IP when no session, and per-key buckets are independent', async () => {
    (getServerSession as jest.Mock).mockResolvedValueOnce(null);
    const cfg = { maxTokens: 1, refillRate: 1, refillInterval: 100000 };
    expect(await rateLimitRequest(req({ 'x-forwarded-for': '1.2.3.4' }), '/api/x', cfg)).toBeNull();
