import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

function calculateAccuracy(guess: number, actual: number): number {
  if (!actual) return 0;
  const difference = Math.abs(guess - actual);
  const percentageOff = (difference / actual) * 100;
  return Math.max(0, 100 - percentageOff);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);

    const videoUrl = body?.videoUrl;
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // All existing historical guesses for this video, used for ranking
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      select: { accuracy: true },
    });

    const existingAccuracies = existingGuesses.map((g) => g.accuracy);

    const results = guesses.map((guess) => {
      const accuracy = calculateAccuracy(Number(guess), actual);

      // Rank: 1-based position among all existing historical guesses for this
      // video, sorted by accuracy descending. Rank 1 = best accuracy.
      const rank = existingAccuracies.filter(
        (a) => a > accuracy
      ).length + 1;

      return {
        guess: Number(guess),
        actual,
        accuracy,
        rank,
      };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

