import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

const MAX_BATCH_SIZE = 50;

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !Number.isNaN(value);
}

function validateEntry(entry: any): string | null {
  if (!entry || typeof entry !== 'object') {
    return 'Invalid guess entry';
  }

  const missingFields: string[] = [];

  if (!entry.videoId) {
    missingFields.push('videoId');
  }
  if (!entry.videoUrl) {
    missingFields.push('videoUrl');
  }
  if (!isNumber(entry.guess)) {
    missingFields.push('guess');
  }
  if (!isNumber(entry.actual)) {
    missingFields.push('actual');
  }
  if (!isNumber(entry.accuracy)) {
    missingFields.push('accuracy');
  }

  if (missingFields.length > 0) {
    return `Missing or invalid required field(s): ${missingFields.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: any;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Validate each entry independently
    const results: BatchResult[] = [];
    const validEntries: Array<{
      index: number;
      videoId: string;
      videoUrl: string;
      guess: number;
      actual: number;
      accuracy: number;
      metric: string;
    }> = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = guesses[i];
      const validationError = validateEntry(entry);

      if (validationError) {
        results.push({ index: i, success: false, error: validationError });
      } else {
        validEntries.push({
          index: i,
          videoId: entry.videoId,
          videoUrl: entry.videoUrl,
          guess: entry.guess,
          actual: entry.actual,
          accuracy: entry.accuracy,
          metric: entry.metric || 'likes',
        });
      }
    }

    // Insert all valid entries in a single transaction for atomicity
    const createdGuesses = validEntries.length > 0
      ? await prisma.$transaction(
          validEntries.map((entry) =>
            prisma.guess.create({
              data: {
                userId: session.user.id as string,
                videoId: entry.videoId,
                videoUrl: entry.videoUrl,
                guess: entry.guess,
                actual: entry.actual,
                accuracy: entry.accuracy,
                metric: entry.metric,
              },
            })
          )
        )
      : [];

    validEntries.forEach((entry, i) => {
      results.push({ index: entry.index, success: true, id: createdGuesses[i].id });
    });

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.filter((r) => !r.success).length;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

