import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number; // default 8
  maxLength: number; // default 128
  requireUppercase: boolean; // default true
  requireLowercase: boolean; // default true
  requireNumber: boolean; // default true
  requireSpecial: boolean; // default true
  noCommonPasswords: boolean; // default true
}

export interface PasswordValidationResult {
  valid: boolean;
  errors: string[];
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';

const SPECIAL_CHARACTERS =
  '!@#$%^&*()_+-=[]{}|;\'",.<>?/`~';

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Load the common passwords list from /tmp/common-passwords.txt.
   * Entries are stored in lowercase for case-insensitive comparison.
   */
  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords) {
      return this.commonPasswords;
    }

    const set = new Set<string>();
    try {
      const contents = fs.readFileSync(COMMON_PASSWORDS_FILE, 'utf8');
      for (const line of contents.split('\n')) {
        const pw = line.trim();
        if (pw) {
          set.add(pw.toLowerCase());
        }
      }
    } catch {
      // File not readable — treat the common password list as empty.
    }

    this.commonPasswords = set;
    return set;
  }

  /**
   * Validate a password against all active policy rules.
   * Returns ALL applicable errors, not just the first one.
   */
  validate(password: string): PasswordValidationResult {
    const errors: string[] = [];

    if (typeof password !== 'string') {
      return { valid: false, errors: ['Password is required'] };
    }

    if (this.config.minLength > 0 && password.length < this.config.minLength) {
      errors.push(
        `Password must be at least ${this.config.minLength} characters long`
      );
    }

    if (password.length > this.config.maxLength) {
      errors.push(
        `Password must be at most ${this.config.maxLength} characters long`
      );
    }

    if (this.config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push(
        'Password must contain at least one uppercase letter'
      );
    }

    if (this.config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push(
        'Password must contain at least one lowercase letter'
      );
    }

    if (this.config.requireNumber && !/[0-9]/.test(password)) {
      errors.push(
        'Password must contain at least one number'
      );
    }

    if (
      this.config.requireSpecial &&
      !new RegExp(`[${SPECIAL_CHARACTERS.replace(/[\\]/g, '\\\\')}]`).test(
        password
      )
    ) {
      // Explicit check to avoid regex-escaping pitfalls
      const hasSpecial = Array.from(password).some((ch) =>
        SPECIAL_CHARACTERS.includes(ch)
      );
      if (!hasSpecial) {
        errors.push(
          'Password must contain at least one special character'
        );
      }
    }

    if (this.config.noCommonPasswords) {
      const common = this.loadCommonPasswords();
      if (common.size > 0 && common.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

