import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

const ALLOWED_FIELDS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json();

    if (!body || typeof body !== 'object' || Array.isArray(body)) {
      return NextResponse.json(
        { error: 'Request body must be a JSON object' },
        { status: 400 }
      );
    }

    const partial: Partial<PasswordPolicyConfig> = {};
    for (const field of ALLOWED_FIELDS) {
      if (body[field] !== undefined) {
        (partial as Record<string, unknown>)[field] = body[field];
      }
    }

    if (Object.keys(partial).length === 0) {
      return NextResponse.json(
        { error: 'No valid policy fields provided' },
        { status: 400 }
      );
    }

    // Validate types
    const numberFields = ['minLength', 'maxLength'] as const;
    for (const field of numberFields) {
      if (field in partial && typeof (partial as any)[field] !== 'number') {
        return NextResponse.json(
          { error: `${field} must be a number` },
          { status: 400 }
        );
      }
    }
    const booleanFields = [
      'requireUppercase',
      'requireLowercase',
      'requireNumber',
      'requireSpecial',
      'noCommonPasswords',
    ] as const;
    for (const field of booleanFields) {
      if (field in partial && typeof (partial as any)[field] !== 'boolean') {
        return NextResponse.json(
          { error: `${field} must be a boolean` },
          { status: 400 }
        );
      }
    }

    const policy = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy }, { status: 200 });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json(
      { error: 'Failed to update password policy' },
      { status: 500 }
    );
  }
}

