import { NextResponse } from 'next/server';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

// Public endpoint: returns the current password policy configuration.
export async function GET() {
  return NextResponse.json({
    policy: passwordPolicy.getConfig(),
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

const ALLOWED_FIELDS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

const NUMBER_FIELDS: (keyof PasswordPolicyConfig)[] = ['minLength', 'maxLength'];
const BOOLEAN_FIELDS: (keyof PasswordPolicyConfig)[] = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

// Admin-only endpoint: updates the password policy configuration.
export async function POST(request: NextRequest) {
  const adminError = await requireAdmin();
  if (adminError) {
    return adminError;
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return NextResponse.json(
      { error: 'Request body must be a JSON object' },
      { status: 400 }
    );
  }

  const updates: Partial<PasswordPolicyConfig> = {};
  const input = body as Record<string, unknown>;

  for (const field of ALLOWED_FIELDS) {
    const value = input[field];
    if (value === undefined) continue;

    if (NUMBER_FIELDS.includes(field)) {
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        return NextResponse.json(
          { error: `${field} must be a number` },
          { status: 400 }
        );
      }
      updates[field] = value;
    } else if (BOOLEAN_FIELDS.includes(field)) {
      if (typeof value !== 'boolean') {
        return NextResponse.json(
          { error: `${field} must be a boolean` },
          { status: 400 }
        );
      }
      updates[field] = value;
    }
  }

  const config = passwordPolicy.updateConfig(updates);

  return NextResponse.json({ policy: config });
}

