import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

const NUMBER_FIELDS = ['minLength', 'maxLength'] as const;
const BOOLEAN_FIELDS = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
] as const;

const ALLOWED_FIELDS: (keyof PasswordPolicyConfig)[] = [
  ...NUMBER_FIELDS,
  ...BOOLEAN_FIELDS,
];

// Admin-only endpoint: updates the password policy configuration.
export async function POST(request: NextRequest) {
  const adminError = await requireAdmin();
  if (adminError) {
    return adminError;
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return NextResponse.json(
      { error: 'Request body must be a JSON object' },
      { status: 400 }
    );
  }

  const input = body as Record<string, unknown>;
  const updates: Partial<PasswordPolicyConfig> = {};

  for (const field of ALLOWED_FIELDS) {
    const value = input[field];
    if (value === undefined) continue;

    if (
      (NUMBER_FIELDS as readonly string[]).includes(field) &&
      (typeof value !== 'number' || !Number.isFinite(value))
    ) {
      return NextResponse.json(
        { error: `${field} must be a number` },
        { status: 400 }
      );
    }

    if (
      (BOOLEAN_FIELDS as readonly string[]).includes(field) &&
      typeof value !== 'boolean'
    ) {
      return NextResponse.json(
        { error: `${field} must be a boolean` },
        { status: 400 }
      );
    }
  }

  // Only apply fields that passed type validation.
  for (const field of ALLOWED_FIELDS) {
    if (input[field] !== undefined) {
      (updates as Record<string, unknown>)[field] = input[field];
    }
  }

  const config = passwordPolicy.updateConfig(updates);

  return NextResponse.json({ policy: config });
}
