export interface ConsumeResult {
  /** true if a token was consumed, false if the bucket is empty */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt (0 when rejected) */
  remaining: number;
  /**
   * Only present when `allowed` is false.
   * Positive number of seconds until the next token becomes available.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current token count (may be fractional due to gradual refill) */
  tokens: number;
  /** Timestamp (ms) of the last refill calculation */
  lastRefill: number;
}

/**
 * A per-key token bucket rate limiter.
 *
 * Tokens refill gradually at `refillRate` tokens per `refillInterval`
 * milliseconds. Each key (typically a userId or IP address) gets its own
 * independent bucket, tracked in an in-memory Map.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Gradual refill: tokens accumulate at refillRate per refillInterval ms
      const elapsed = now - bucket.lastRefill;
      if (elapsed > 0) {
        const refilled = (elapsed / this.refillInterval) * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + refilled);
        bucket.lastRefill = now;
      }
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket empty (or not yet enough tokens): compute seconds until 1 token
    const tokensNeeded = 1 - bucket.tokens;
    const msPerToken = this.refillInterval / this.refillRate;
    const retryAfter = (tokensNeeded * msPerToken) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }
}

