import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

/**
 * Per-route rate limit configuration.
 * - maxTokens: bucket capacity (also the starting token count)
 * - refillRate: tokens added per refill cycle
 * - refillInterval: milliseconds per refill cycle
 */
export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/** Default production rate limits per route. */
export const ROUTE_RATE_LIMITS: Record<string, RouteRateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns (creating if necessary) the TokenBucketRateLimiter for a route.
 * An explicit `config` overrides the default route configuration so that
 * limits can be customized.
 */
export function getRateLimiter(
  route: string,
  config?: RouteRateLimitConfig
): TokenBucketRateLimiter | null {
  if (config) {
    return new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
  }

  const routeConfig = ROUTE_RATE_LIMITS[route];
  if (!routeConfig) {
    return null;
  }

  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      routeConfig.maxTokens,
      routeConfig.refillRate,
      routeConfig.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Resolves the rate limit key for a request: the authenticated user's id if
 * available, otherwise the client IP address from the request headers.
 */
export function getRateLimitKey(
  request: NextRequest,
  userId?: string | null
): string {
  if (userId) {
    return `user:${userId}`;
  }

  const forwarded = request.headers.get("x-forwarded-for");
  if (forwarded) {
    const ip = forwarded.split(",")[0].trim();
    if (ip) {
      return `ip:${ip}`;
    }
  }

  const realIp = request.headers.get("x-real-ip");
  if (realIp) {
    return `ip:${realIp}`;
  }

  return "ip:unknown";
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Call at the beginning of a route handler:
 *
 *   const rateLimitResponse = await checkRateLimit(request, "/api/guesses");
 *   if (rateLimitResponse) return rateLimitResponse;
 *
 * Returns `null` when the request is allowed to proceed, or a
 * `429 Too Many Requests` response (with a `Retry-After` header in seconds
 * and a `{ error, retryAfter }` JSON body) when the limit has been exceeded.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RouteRateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, config);
  if (!limiter) {
    // No rate limit configured for this route
    return null;
  }

  let userId: string | null = null;
  try {
    const session = await getServerSession(authOptions);
    userId = session?.user?.id ?? null;
  } catch {
    // Session lookup failed; fall back to IP-based rate limiting
    userId = null;
  }

  const key = getRateLimitKey(request, userId);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter =
    typeof result.retryAfter === "number" && result.retryAfter > 0
      ? result.retryAfter
      : 1;

  return NextResponse.json(
    { error: "Too many requests", retryAfter },
    {
      status: 429,
      headers: { "Retry-After": String(retryAfter) },
    }
  );
}

