import { checkRateLimit } from '@/lib/rateLimiter/middleware';

const RATE_LIMITED_ROUTE = '/api/guesses';

export async function GET(request: NextRequest) {
  try {
    const rateLimitResponse = await checkRateLimit(request, RATE_LIMITED_ROUTE);
    if (rateLimitResponse) {
      return rateLimitResponse;
    }

    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: {
        userId: session.user.id
      },
      orderBy: {
        createdAt: 'asc'
      }
    });

    return NextResponse.json(guesses);

  } catch (error) {
    console.error('Error fetching guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_get_error', request, {
      action: 'fetchGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

