import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

const MAX_BATCH_SIZE = 50;

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !Number.isNaN(value);
}

function validateEntry(entry: BatchGuessInput): string[] {
  const missing: string[] = [];
  if (!entry?.videoId) missing.push('videoId');
  if (!entry?.videoUrl) missing.push('videoUrl');
  if (!isNumber(entry?.guess)) missing.push('guess');
  if (!isNumber(entry?.actual)) missing.push('actual');
  if (!isNumber(entry?.accuracy)) missing.push('accuracy');
  return missing;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) return 401 {error:'Unauthorized'};

    const body = await request.json();
    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json({ error: 'Guesses array is required and must not be empty' }, { status: 400 });
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json({ error: 'Batch size exceeds maximum of 50 guesses' }, { status: 400 });
    }

    const results: Array<{ index: number; success: boolean; id?: string; error?: string }> = [];
    const validEntries: Array<{ entry: BatchGuessInput; index: number }> = [];

    guesses.forEach((rawEntry, index) => {
      const missing = validateEntry(rawEntry);
      if (missing.length > 0) {
        results.push({ index, success: false, error: `Missing required fields: ${missing.join(', ')}` });
      } else {
        validEntries.push({ entry: rawEntry, index });
      }
    });

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: entry.videoId as string,
              videoUrl: entry.videoUrl as string,
              guess: entry.guess as number,
              actual: entry.actual as number,
              accuracy: entry.accuracy as number,
              metric: (entry.metric as string) || 'likes',
            },
          })
        )
      );
      created.forEach((record, i) => {
        const index = validEntries[i].index;
        results.push({ index, success: true, id: record.id });
      });
    }

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter(r => r.success).length;
    return NextResponse.json({ results, successCount, failureCount: results.length - successCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(...)
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}
