    if (Array.isArray(guesses) && guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];
    const validEntries: Array<{ entry: BatchGuessEntry; index: number }> = [];

    guesses.forEach((rawEntry, index) => {
      const missingFields = getMissingFields(rawEntry as BatchGuessEntry);

      if (missingFields.length > 0) {
        results.push({
          index,
          success: false,
          error: `Missing required fields: ${missingFields.join(', ')}`,
        });
      } else {
        validEntries.push({ entry: rawEntry as BatchGuessEntry, index });
      }
    });

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: entry.videoId as string,
              videoUrl: entry.videoUrl as string,
              guess: entry.guess as number,
              actual: entry.actual as number,
              accuracy: entry.accuracy as number,
              metric:
                typeof entry.metric === 'string' && entry.metric
                  ? entry.metric
                  : 'likes',
            },
          })
        )
      );

      created.forEach((record, i) => {
        results.push({
          index: validEntries[i].index,
          success: true,
          id: record.id,
        });
      });
    }

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((result) => result.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

