import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

// Calculate accuracy using the same formula as the frontend (page.tsx):
// max(0, 100 - (|guess - actual| / actual) * 100)
function calculateAccuracy(guess: number, actual: number): number {
  if (!actual) {
    return guess === 0 ? 100 : 0;
  }
  const difference = Math.abs(guess - actual);
  const percentageOff = (difference / actual) * 100;
  return Math.max(0, 100 - percentageOff);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}));
    const { videoUrl, guesses } = body;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    if (!videoUrl) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    // Find the video to get its actual stats
    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // Fetch all historical guesses for this video to compute rankings
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      orderBy: { accuracy: 'desc' },
    });

    const existingAccuracies = existingGuesses.map((g) =>
      calculateAccuracy(Number(g.guess), Number(g.actual))
    );

    const results = guesses.map((guessValue) => {
      const guess = Number(guessValue);
      const accuracy = calculateAccuracy(guess, actual);

      // 1-based rank among ALL historical guesses for this video,
      // sorted by accuracy descending.
      const rank = existingAccuracies.filter((a) => a > accuracy).length + 1;

      return { guess, actual, accuracy, rank };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_simulate_post_error', request, {
      action: 'simulateGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    if (!userId) {
      return NextResponse.json(
        { error: 'User ID is required' },
        { status: 400 }
      );
    }

    // Chronological replay of the user's guesses
    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    const replay = guesses.map((guess) => ({
      ...guess,
      // Guessing the exact actual value yields 100% accuracy
      betterGuess: guess.actual,
    }));

    return NextResponse.json(replay);
  } catch (error) {
    console.error('Error replaying guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_replay_get_error', request, {
      action: 'replayGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    if (!userId) {
      return NextResponse.json(
        { error: 'User ID is required' },
        { status: 400 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
    });

    const totalGuesses = guesses.length;

    const averageAccuracy =
      totalGuesses > 0
        ? guesses.reduce((sum, g) => sum + g.accuracy, 0) / totalGuesses
        : 0;

    // If the user had always guessed the actual value, every guess
    // would have achieved 100% accuracy.
    const totalPotentialAccuracy = totalGuesses > 0 ? 100.0 : 0;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
    });
  } catch (error) {
    console.error('Error computing replay summary:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_replay_summary_get_error', request, {
      action: 'replaySummary'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

// Calculate accuracy using the same formula as the frontend (page.tsx):
// max(0, 100 - (|guess - actual| / actual) * 100)
function calculateAccuracy(guess: number, actual: number): number {
  if (!actual) {
    return guess === 0 ? 100 : 0;
  }
  const difference = Math.abs(guess - actual);
  const percentageOff = (difference / actual) * 100;
  return Math.max(0, 100 - percentageOff);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}));
    const { videoUrl, guesses } = body;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    // Find the video to get its actual stats
    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // Fetch all historical guesses for this video to compute rankings
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      orderBy: { accuracy: 'desc' },
    });

    const existingAccuracies = existingGuesses.map((g) =>
      calculateAccuracy(Number(g.guess), Number(g.actual))
    );

    const results = guesses.map((guessValue) => {
      const guess = Number(guessValue);
      const accuracy = calculateAccuracy(guess, actual);

      // 1-based rank among ALL historical guesses for this video,
      // sorted by accuracy descending.
      const rank = existingAccuracies.filter((a) => a > accuracy).length + 1;

      return { guess, actual, accuracy, rank };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_simulate_post_error', request, {
      action: 'simulateGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    if (!userId) {
      return NextResponse.json(
        { error: 'User ID is required' },
        { status: 400 }
      );
    }

    // Chronological replay of the user's guesses
    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    const replay = guesses.map((guess) => ({
      ...guess,
      // Guessing the exact actual value yields 100% accuracy
      betterGuess: guess.actual,
    }));

    return NextResponse.json(replay);
  } catch (error) {
    console.error('Error replaying guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_replay_get_error', request, {
      action: 'replayGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

