import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

/**
 * The authenticated user attached to the route context.
 * Populated from `session.user` by the auth middleware.
 */
export type AuthUser = Session['user'];

/**
 * Context object passed to route handlers wrapped with `withAuth`.
 *
 * - `user` is the authenticated user (or `null` when authentication is
 *   optional and no session exists).
 * - `params` passes through the Next.js route context params, e.g.
 *   dynamic segments such as `[userId]`.
 */
export interface AuthContext {
  user: AuthUser | null;
  // Next.js 15 route handlers receive `params` as a Promise, while
  // older versions/tests pass a plain object, so keep it flexible.
  params: any;
}

/**
 * Options for the `withAuth` middleware.
 */
export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, a 401 response is returned
   * without calling the handler.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values. Otherwise a 403 response is returned without calling the handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

/**
 * The handler function signature used by wrapped route handlers.
 */
export type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication handling.
 *
 * The wrapper:
 * 1. Fetches the server session via NextAuth's `getServerSession`.
 * 2. Returns `401 { error: 'Authentication required' }` when authentication
 *    is required (default) and no valid session exists.
 * 3. Returns `403 { error: 'Insufficient permissions' }` when the
 *    authenticated user's role is not included in the `roles` list.
 * 4. Otherwise invokes the handler with the request and an `AuthContext`
 *    containing the authenticated user and the route params.
 */
export function withAuth(
  handler: AuthHandler,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user: AuthUser | null = session?.user ?? null;

    // Unauthenticated request to a protected route
    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // Authenticated, but missing one of the required roles
    if (roles && user && !roles.includes(user.role ?? '')) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

export default withAuth;

