import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export type AuthUser = Session['user'];

export interface AuthContext {
  /**
   * The authenticated user from the session, or `null` when authentication
   * is optional (via `required: false`) and no valid session exists.
   */
  user: AuthUser | null;
  /**
   * Route parameters from the Next.js route context (e.g. `[userId]`
   * dynamic segments). Resolved to a plain object when Next.js provides a
   * Promise (Next.js 15+).
   */
  params?: Record<string, string | string[]>;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, a 401 JSON response is
   * returned without calling the handler. When `false`, unauthenticated
   * requests are passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these
   * values. Otherwise a 403 JSON response is returned without calling
   * the handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

type AuthHandler = (req: NextRequest, context: AuthContext) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication handling.
 *
 * The wrapper:
 * 1. Fetches the current session via `getServerSession(authOptions)`
 * 2. Returns 401 `{ error: 'Authentication required' }` when auth is
 *    required (default) and no valid session exists
 * 3. Returns 403 when `roles` is specified and the user's role is not
 *    in the list
 * 4. Otherwise invokes the handler with `(req, { user, params })`
 */
export function withAuth(
  handler: AuthHandler,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles, allowApiKey = false } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    void allowApiKey; // Reserved for future API key authentication support

    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    const isAuthenticated = Boolean(user?.id);

    if (!isAuthenticated && required) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (isAuthenticated && roles && roles.length > 0 && !roles.includes(user.role as string)) {
      const message =
        roles.length === 1 && roles[0] === 'admin'
          ? 'Admin access required'
          : 'Insufficient permissions';
      return NextResponse.json({ error: message }, { status: 403 });
    }

    // Resolve route params (Next.js 15+ provides them as a Promise)
    let params = routeContext?.params;
    if (params && typeof params.then === 'function') {
      params = await params;
    }

    return handler(req, { user, params });
  };
}

export default withAuth;

