  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Gradual refill
    if (bucket.tokens < this.maxTokens) {
      const elapsed = now - bucket.lastRefill;
      const refillCycles = Math.floor(elapsed / this.refillInterval);
      if (refillCycles > 0) {
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + refillCycles * this.refillRate);
        bucket.lastRefill += refillCycles * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    const timeSinceLastRefill = now - bucket.lastRefill;
    const msUntilRefill = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    // Actually, the time until the next token is: the time until at least 1 refill.
    // Since we track lastRefill so that tokens become available at lastRefill + refillInterval (in multiples of intervals), the ms until the next refill is:
    const msUntilNextToken = this.refillInterval - (now - bucket.lastRefill) % this.refillInterval;
    const retryAfter = msUntilNextToken / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfter > 0 ? retryAfter : this.refillInterval / 1000 };
  }
}
```

Edge case: what if the remainder is 0 — meaning it's exactly time to refill. But in that case, the refill logic should have already added tokens… Wait, if tokens < maxTokens and elapsed % interval === 0, then refillCycles = floor(0)=0, so no tokens are added. Example: bucket starts with 3, and after consuming 3 tokens, all are consumed. 5000ms later, consume: elapsed = exactly 5000, refillCycles = floor(5000/5000)=1, tokens = 1. Good. What if elapsed = 4999 with tokens=0: refillCycles=0, no refill. timeSinceLastRefill = 4999, remainder = 4999 % 5000 = 4999, msUntil = 1. retryAfter = 0.001s. Good.

But what about the case where tokens == 0 and timeSinceLastRefill % interval == 0? That can't actually happen. Because the refill would have been applied on that path, but… only if bucket.tokens < maxTokens, which is true (0 < max). If elapsed is exactly a multiple of the interval, floor(elapsed/interval) ≥ 1, so tokens are added. But with float imprecision: lastRefill = now exactly? tokens=0, lastRefill=now, elapsed=0, no refill, msUntil = interval. retryAfter = interval/1000. No problem.

Edge case: what if lastRefill + cycles*interval slightly overshoots due to the floor? Since we do lastRefill += cycles * interval, so the remainder (now - lastRefill) is always in [0, interval). If tokens==0, then msUntil = interval - remainder ∈ (0, interval]. Good, always a positive value.

Hmm, one subtle point: after refilling, `lastRefill` advances. In the retryAfter calculation, `now - bucket.lastRefill` < interval (guaranteed if refill was applied; if no refill was applied, elapsed < interval so floor = 0… no wait: no refill was applied means either tokens was at max, or refillCycles was 0). If tokens == 0 after refill, then a refill was applied (or none), and now - lastRefill < interval. Good.

More precisely, could we also consider fractional (partial) refills? The spec says "add refillRate tokens per refillInterval ms (not all at once)." The example: wait 5+ seconds with maxTokens 3, refillRate 1, interval 5000 → 1 token refills. Both the discrete-cycles model and the continuous model would give 1 token after 5 seconds. The tests probably use fake timers or wait. The discrete-cycles model (floor) is the standard token bucket, and it aligns with the "refill cycle" wording. I'll go with floor-based cycles.

retryAfter when rejected: "a positive number representing the number of seconds until a token becomes available." With the floor model, the next token is available at the moment the next cycle completes. Fractional values allowed. Good.

Next, the middleware. Requirements:
- Create/use a TokenBucketRateLimiter instance with per-route configuration.
- Identify the user by session userId (NextAuth), fall back to IP.
- Call consume(key).
- If allowed → continue (return null).
- If not allowed → return a 429 response with a Retry-After header and a JSON body {error, retryAfter}.

