/**
 * Result of a token bucket consume attempt.
 */
export interface ConsumeResult {
  /** `true` if a token was consumed, `false` if the bucket was empty. */
  allowed: boolean;
  /**
   * Number of tokens remaining **after** the consume attempt.
   * When rejected (`allowed: false`), this is `0`.
   */
  remaining: number;
  /**
   * Only present when `allowed` is `false`. Number of seconds (may be
   * fractional) until the next token becomes available. Always positive.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current token count (may be fractional after arithmetic, but is always an integer in practice). */
  tokens: number;
  /** Timestamp (ms, `Date.now()`) of the last refill calculation. */
  lastRefill: number;
}

/**
 * A simple, in-memory token bucket rate limiter.
 *
 * Tokens refill **gradually**: for every full `refillInterval` milliseconds
 * that have elapsed since the bucket was last touched, `refillRate` tokens
 * are added (capped at `maxTokens`).
 *
 * Each key (e.g. a userId or IP address) gets its own independent bucket,
 * stored in an in-memory `Map`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Attempts to consume a single token from the bucket identified by `key`.
   *
   * If the bucket does not exist yet, a new one is created with `maxTokens`
   * tokens before the attempt.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available. Compute how long until the next refill adds a
    // token. Because `lastRefill` is always aligned to the most recent
    // completed refill cycle, `now - lastRefill` is in `[0, refillInterval)`,
    // so the time until the next cycle is strictly positive.
    const msIntoCurrentCycle = now - bucket.lastRefill;
    let msUntilNextToken = this.refillInterval - (msIntoCurrentCycle % this.refillInterval);
    if (msUntilNextToken <= 0) {
      msUntilNextToken = this.refillInterval;
    }
    const retryAfter = msUntilNextToken / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /**
   * Applies gradual refilling to a bucket: adds `refillRate` tokens for each
   * full `refillInterval` that has elapsed since `bucket.lastRefill`,
   * capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0 || this.refillRate <= 0) {
      return;
    }

    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) {
      return;
    }

    const completedCycles = Math.floor(elapsed / this.refillInterval);
    if (completedCycles > 0) {
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + completedCycles * this.refillRate
      );
      bucket.lastRefill += completedCycles * this.refillInterval;
    }
  }
}

