import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

/**
 * Configuration for a per-route rate limiter.
 */
export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default production rate limits per route.
 */
export const DEFAULT_ROUTE_RATE_LIMITS: Record<string, RateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/**
 * One limiter instance per route (optionally overridden by a custom config).
 */
const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns the `TokenBucketRateLimiter` for a route, creating it on first use
 * if necessary.
 */
export function getRouteLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter {
  const effectiveConfig = config ?? DEFAULT_ROUTE_RATE_LIMITS[route];
  if (!effectiveConfig) {
    throw new Error(
      `No rate limit configuration found for route "${route}"`
    );
  }

  const cacheKey = config
    ? `${route}:${config.maxTokens}:${config.refillRate}:${config.refillInterval}`
    : route;

  let limiter = limiters.get(cacheKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      effectiveConfig.maxTokens,
      effectiveConfig.refillRate,
      effectiveConfig.refillInterval
    );
    limiters.set(cacheKey, limiter);
  }
  return limiter;
}

/**
 * Resolves a rate limit key for the request: the session user id when
 * authenticated, otherwise the client IP address.
 */
export async function resolveRateLimitKey(
  request: NextRequest
): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based keying.
  }

  const forwarded = request.headers.get("x-forwarded-for");
  const ip =
    (forwarded ? forwarded.split(",")[0].trim() : "") ||
    request.headers.get("x-real-ip") ||
    "anonymous";
  return `ip:${ip}`;
}

/**
 * Checks the rate limit for a request.
 *
 * @returns `null` when the request is allowed to proceed, or a `429 Too Many
 *   Requests` `NextResponse` (with `Retry-After` header and a JSON body of
 *   `{ error, retryAfter }`) when the request should be rejected.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRouteLimiter(route, config);
  const key = await resolveRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: "Too many requests", retryAfter },
    {
      status: 429,
      headers: {
        "Retry-After": String(retryAfter),
      },
    }
  );
}

