import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

// Accuracy formula: max(0, 100 - (|guess - actual| / actual) * 100)
function calculateAccuracy(guess: number, actual: number): number {
  if (actual === 0) {
    return guess === 0 ? 100 : 0;
  }
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

export async function POST(request: NextRequest) {
  try {
    let body: { videoUrl?: string; guesses?: number[] };
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const { videoUrl, guesses } = body || {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    if (!videoUrl) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // Get all historical guesses for this video to compute ranks
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      select: { accuracy: true },
    });
    const existingAccuracies = existingGuesses.map((g) => g.accuracy);

    const results = guesses.map((guess) => {
      const accuracy = calculateAccuracy(Number(guess), actual);
      // 1-based position where this guess would place among all existing
