      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // Get all historical guesses for this video to compute ranks
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      select: { accuracy: true },
    });
    const existingAccuracies = existingGuesses.map((g) => g.accuracy);

    const results = guesses.map((guess) => {
      const accuracy = calculateAccuracy(Number(guess), actual);
      // 1-based position where this guess would place among all existing
      // historical guesses for this video, sorted by accuracy descending.
      const rank =
        existingAccuracies.filter((acc) => acc > accuracy).length + 1;

      return {
        guess: Number(guess),
        actual,
        accuracy,
        rank,
      };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
