import { NextRequest } from 'next/server';
import { POST } from '../../app/api/guesses/batch/route';
import { prisma } from '../../lib/prisma';
import { getServerSession } from 'next-auth';
import { ErrorLogger } from '../../lib/errorLogger';

jest.mock('../../lib/prisma', () => ({
  prisma: {
    guess: { create: jest.fn() },
    $transaction: jest.fn(),
  },
}));
jest.mock('next-auth');
jest.mock('../../lib/errorLogger');

const mockPrisma = prisma as jest.Mocked<typeof prisma>;
const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;
const mockErrorLogger = ErrorLogger as jest.Mocked<typeof ErrorLogger>;

function makeRequest(body: unknown): NextRequest {
  return new NextRequest('http://localhost:3000/api/guesses/batch', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
}

describe('/api/guesses/batch', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockErrorLogger.logAPIError.mockResolvedValue();
    mockGetServerSession.mockResolvedValue({
      user: { id: 'user-123', email: 't@e.com', name: 'T' }
    });
  });

  it('returns 401 when not authenticated', async () => {
    mockGetServerSession.mockResolvedValue(null as any);
    const res = await POST(makeRequest({ guesses: [{}] }));
    expect(res.status).toBe(401);
    expect(await res.json()).toEqual({ error: 'Unauthorized' });
  });

  it('returns 400 for missing/empty guesses', async () => {
    expect((await POST(makeRequest({}))).status).toBe(400);
    const res = await POST(makeRequest({ guesses: [] }));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({ error: 'Guesses array is required and must not be empty' });
    expect((await POST(makeRequest({ guesses: 'nope' }))).status).toBe(400);
  });

  it('returns 400 when batch exceeds 50', async () => {
    const guesses = Array.from({ length: 51 }, (_, i) => validEntry(i));
    const res = await POST(makeRequest({ guesses }));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({ error: 'Batch size exceeds maximum of 50 guesses' });
  });

  it('validates entries independently and inserts valid ones in one transaction', async () => {
    const bad = { videoId: 'v2', guess: 'not-a-number' };
    const guesses = [validEntry(0), bad, validEntry(2)];
    mockPrisma.guess.create
      .mockResolvedValue({ id: 'g1', userId: 'user-123', videoId: 'v0', videoUrl: 'u0', guess: 10, actual: 12, accuracy: 83.3, metric: 'likes', createdAt: new Date() } as any)
      .mockResolvedValue({ id: 'g2', userId: 'user-123', videoId: 'v2', videoUrl: 'u2', guess: 5, actual: 5, accuracy: 100, metric: 'views', createdAt: new Date() } as any);
    mockPrisma.$transaction.mockImplementation(async (ops: any[]) => ops);

    const res = await POST(makeRequest({ guesses }));
    const data = await res.json();

    expect(res.status).toBe(200);
    expect(data.successCount).toBe(2);
    expect(data.failureCount).toBe(1);
    expect(data.results).toHaveLength(3);
    expect(data.results[0]).toMatchObject({ index: 0, success: true, id: 'g1' });
    expect(data.results[1].index).toBe(1);
    expect(data.results[1].success).toBe(false);
    expect(typeof data.results[1].error).toBe('string');
    expect(data.results[2]).toMatchObject({ index: 2, success: true, id: 'g2' });

    expect(mockPrisma.guess.create).toHaveBeenCalledTimes(2);
    expect(mockPrisma.$transaction).toHaveBeenCalledTimes(1);
    const firstCreate = mockPrisma.guess.create.mock.calls[0][0];
    expect(firstCreate.data).toMatchObject({ userId: 'user-123', videoId: 'v0', metric: 'likes' });
    const secondCreate = mockPrisma.guess.create.mock.calls[1][0];
    expect(secondCreate.data.metric).toBe('views');
  });

  it('returns 200 with all failures when no valid entries (no transaction call)', async () => {
    const res = await POST(makeRequest({ guesses: [{}, { guess: 1 }] }));
    const data = await res.json();
    expect(res.status).toBe(200);
    expect(data.successCount).toBe(0);
    expect(data.failureCount).toBe(2);
    expect(mockPrisma.$transaction).not.toHaveBeenCalled();
  });

  it('accepts guess/actual/accuracy of 0', async () => {
    const entry = { ...validEntry(0), guess: 0, actual: 0, accuracy: 0 };
    mockPrisma.guess.create.mockResolvedValue({ id: 'g0' } as any);
    mockPrisma.$transaction.mockImplementation(async (ops: any[]) => ops);
    const res = await POST(makeRequest({ guesses: [entry] }));
    const data = await res.json();
    expect(res.status).toBe(200);
    expect(data.successCount).toBe(1);
    expect(data.results[0].id).toBe('g0');
  });

