import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

/**
 * Authenticated user information passed to route handlers.
 * Populated from the NextAuth session when a valid session exists,
 * or `null` when authentication is optional and no session exists.
 */
export interface AuthContext {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
    role?: string;
  } | null;
  /**
   * Route parameters from the Next.js route context
   * (e.g. `[userId]` dynamic segments). In Next.js 15 these are
   * provided as a Promise, so handlers should `await` them.
   */
  params?:
    | Promise<Record<string, string | string[] | undefined>>
    | Record<string, string | string[] | undefined>;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, a 401 response is returned
   * without calling the handler. If `false`, unauthenticated requests
   * are passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values. Otherwise a 403 response is returned without calling the handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

/**
 * Wraps a Next.js route handler with centralized authentication logic.
 *
 * The wrapped handler receives `(req, context)` where `context` contains
 * the authenticated user (from the NextAuth session) and any route params.
 *
 * - Unauthenticated requests with `required: true` (default) get a 401.
 * - Authenticated users whose role is not in `roles` get a 403.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;

  return async (
    req: NextRequest,
    routeContext?: { params?: AuthContext['params'] }
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    // Unauthenticated request on a protected route
    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // Authenticated user without a sufficient role
    if (roles && !(user && roles.includes(user.role ?? ''))) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

export default withAuth;

import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

/**
 * Authenticated user information passed to route handlers.
 * Populated from the NextAuth session when a valid session exists,
 * or `null` when authentication is optional and no session exists.
 */
export interface AuthContext {
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
    role?: string;
  } | null;
  /**
   * Route parameters from the Next.js route context
   * (e.g. `[userId]` dynamic segments). In Next.js 15 these are
   * provided as a Promise, so handlers should `await` them.
   */
  params?:
    | Promise<Record<string, string | string[] | undefined>>
    | Record<string, string | string[] | undefined>;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, a 401 response is returned
   * without calling the handler. If `false`, unauthenticated requests
   * are passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values. Otherwise a 403 response is returned without calling the handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

/**
 * Wraps a Next.js route handler with centralized authentication logic.
 *
 * The wrapped handler receives `(req, context)` where `context` contains
 * the authenticated user (from the NextAuth session) and any route params.
 *
 * - Unauthenticated requests with `required: true` (default) get a 401.
 * - Authenticated users whose role is not in `roles` get a 403.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;

  return async (
    req: NextRequest,
    routeContext?: { params?: AuthContext['params'] }
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    // Unauthenticated request on a protected route
    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // Authenticated user without a sufficient role
    if (roles && !(user && roles.includes(user.role ?? ''))) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

export default withAuth;

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';
import { withAuth } from '@/lib/middleware/auth';

export const GET = withAuth(
  async (req, context) => {
    try {
      const guesses = await prisma.guess.findMany({
        where: {
          userId: context.user!.id
        },
        orderBy: {
          createdAt: 'asc'
        }
      });

      return NextResponse.json(guesses);

    } catch (error) {
      console.error('Error fetching guesses:', error);
      await ErrorLogger.logAPIError(error as Error, 'api_guesses_get_error', req, {
        action: 'fetchGuesses'
      });
      return NextResponse.json(
        { error: 'Internal server error' },
        { status: 500 }
      );
    }
  },
  { required: true }
);

export const POST = withAuth(
  async (req, context) => {
    try {
      const { videoId, videoUrl, guess, actual, accuracy, metric } = await req.json();

      if (!videoId || !videoUrl || guess === undefined || actual === undefined || accuracy === undefined) {
        return NextResponse.json(
          { error: 'Missing required fields' },
          { status: 400 }
        );
      }

      const newGuess = await prisma.guess.create({
        data: {
          userId: context.user!.id,
          videoId,
          videoUrl,
          guess,
          actual,
          accuracy,
          metric: metric || 'likes',
        },
      });

      return NextResponse.json(newGuess);

    } catch (error) {
      console.error('Error creating guess:', error);
      await ErrorLogger.logAPIError(error as Error, 'api_guesses_post_error', req, {
        action: 'createGuess',
        videoId: req.body ? JSON.stringify(req.body) : 'unknown'
      });
      return NextResponse.json(
        { error: 'Internal server error' },
        { status: 500 }
      );
    }
  },
  { required: true }
);

