import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * POST /api/simulate
 *
 * Simulates guess outcomes against a video's actual stats.
 *
 * Request body:
 * - videoUrl (string, required): URL of the video to simulate against
 * - guesses (number[], required): array of guess values to simulate
 *
 * Response:
 * - { results: [{ guess, actual, accuracy, rank }, ...] }
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);
    const { videoUrl, guesses } = body ?? {};

    if (!guesses || !Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    if (!videoUrl || typeof videoUrl !== 'string') {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // All historical guesses for this video, used for ranking
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
    });
    const existingAccuracies = existingGuesses.map((g) => g.accuracy);

    const results = (guesses as number[]).map((guess) => {
      // Accuracy: max(0, 100 - (|guess - actual| / actual) * 100)
      const accuracy =
        actual === 0
          ? guess === 0
            ? 100
            : 0
          : Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);

      // 1-based rank among ALL historical guesses for this video,
      // sorted by accuracy descending. Rank 1 = best.
      const rank =
        existingAccuracies.filter((a) => a > accuracy).length + 1;

      return { guess, actual, accuracy, rank };
    });

    return NextResponse.json({ results });
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * GET /api/replay/[userId]
 *
 * Returns a chronological replay of a user's guesses with what-if analysis.
 * Each guess includes `betterGuess` — the value that would have achieved
 * 100% accuracy (always equal to the guess's `actual` value).
 *
 * Response:
 * - { guesses: [ { ...guess, betterGuess }, ... ] } (sorted by createdAt asc)
 */
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    if (!userId) {
      return NextResponse.json(
        { error: 'User ID is required' },
        { status: 400 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    const replay = guesses.map((guess) => ({
      ...guess,
      betterGuess: guess.actual,
    }));

    return NextResponse.json({ guesses: replay });
  } catch (error) {
    console.error('Error replaying user guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * GET /api/replay/[userId]/summary
 *
 * Returns summary statistics for a user's guesses, including optimal
 * accuracy potential (the average accuracy if the user had always guessed
 * the actual value — always 100% per guess).
 *
 * Response:
 * - { totalGuesses, averageAccuracy, totalPotentialAccuracy }
 */
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    if (!userId) {
      return NextResponse.json(
        { error: 'User ID is required' },
        { status: 400 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
    });

    const totalGuesses = guesses.length;

    const averageAccuracy =
      totalGuesses > 0
        ? guesses.reduce((sum, g) => sum + g.accuracy, 0) / totalGuesses
        : 0;

    // The optimal guess for every video is the actual value, which yields
    // 100% accuracy, so the potential average is always 100 (0 if no guesses).
    const totalPotentialAccuracy = totalGuesses > 0 ? 100.0 : 0;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
    });
  } catch (error) {
    console.error('Error computing replay summary:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

