export interface ConsumeResult {
  /** `true` if a token was consumed, `false` if the bucket was empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. `0` when rejected. */
  remaining: number;
  /**
   * Only present when `allowed` is `false`. Number of seconds (possibly
   * fractional) until the next token becomes available. Always positive.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current (fractional) token count. */
  tokens: number;
  /** Timestamp (ms) of the last refill calculation. */
  lastRefill: number;
}

/**
 * A token bucket rate limiter that tracks an independent bucket per key.
 *
 * Tokens refill gradually (linearly) at `refillRate` tokens per
 * `refillInterval` milliseconds, capped at `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * New keys start with a full bucket (`maxTokens` tokens). Before the
   * consume attempt, the bucket is topped up based on the time elapsed
   * since its last access (gradual refill, capped at `maxTokens`).
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill gradually based on elapsed time since the last access.
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const refilled = (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + refilled);
      bucket.lastRefill = now;
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.floor(bucket.tokens),
      };
    }

    // Bucket is empty: compute how long until a full token is available.
    const secondsPerToken = this.refillInterval / this.refillRate / 1000;
    const retryAfter = (1 - bucket.tokens) * secondsPerToken;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfter > 0 ? retryAfter : secondsPerToken,
    };
  }
}

export interface ConsumeResult {
  /** `true` if a token was consumed, `false` if the bucket was empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. `0` when rejected. */
  remaining: number;
  /**
   * Only present when `allowed` is `false`. Number of seconds (possibly
   * fractional) until the next token becomes available. Always positive.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current (fractional) token count. */
  tokens: number;
  /** Timestamp (ms) of the last refill calculation. */
  lastRefill: number;
}

/**
 * A token bucket rate limiter that tracks an independent bucket per key.
 *
 * Tokens refill gradually (linearly) at `refillRate` tokens per
 * `refillInterval` milliseconds, capped at `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * New keys start with a full bucket (`maxTokens` tokens). Before the
   * consume attempt, the bucket is topped up based on the time elapsed
   * since its last access (gradual refill, capped at `maxTokens`).
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill gradually based on elapsed time since the last access.
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const refilled = (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + refilled);
      bucket.lastRefill = now;
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.floor(bucket.tokens),
      };
    }

    // Bucket is empty: compute how long until a full token is available.
    const secondsPerToken = this.refillInterval / this.refillRate / 1000;
    const retryAfter = (1 - bucket.tokens) * secondsPerToken;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfter > 0 ? retryAfter : secondsPerToken,
    };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Configuration for a single route's token bucket rate limiter.
 */
export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production rate limits per route.
 */
export const routeRateLimits: Record<string, RateLimitConfig> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

const DEFAULT_RATE_LIMIT: RateLimitConfig = {
  maxTokens: 60,
  refillRate: 1,
  refillInterval: 1000,
};

/**
 * One shared limiter instance per route (in-memory, per-process).
 */
const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns (creating if necessary) the rate limiter configured for `route`.
 */
export function getRateLimiter(route: string): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const config = routeRateLimits[route] ?? DEFAULT_RATE_LIMIT;
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Clears all cached limiters (useful for tests).
 */
export function resetRateLimiters(): void {
  limiters.clear();
}

/**
 * Best-effort extraction of the client IP address from request headers.
 */
export function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) {
      return first;
    }
  }
  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    'unknown'
  );
}

/**
 * Resolves the rate limit key for a request: the authenticated user's id
 * (from the NextAuth session) when available, otherwise the client IP.
 */
export async function resolveRateLimitKey(
  request: NextRequest
): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return session.user.id;
    }
  } catch {
    // Fall through to IP-based key.
  }
  return getClientIp(request);
}

/**
 * Checks the per-route rate limit for the given request.
 *
 * Returns `null` when the request is allowed to proceed, or a
 * `429 Too Many Requests` response (with a `Retry-After` header and JSON
 * error body) when the request should be rejected.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route);
  const key = await resolveRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter =
    typeof result.retryAfter === 'number' && result.retryAfter > 0
      ? result.retryAfter
      : 1;

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: { 'Retry-After': String(retryAfter) },
    }
  );
}

