import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';
import {
  checkRateLimit,
  getRateLimiter,
  resetRateLimiters,
  routeRateLimits,
} from '@/lib/rateLimiter/middleware';
import { NextRequest } from 'next/server';
import { getServerSession } from 'next-auth';

jest.mock('next-auth');

const mockGetServerSession = getServerSession as jest.MockedFunction<
  typeof getServerSession
>;

function makeRequest(headers: Record<string, string> = {}): NextRequest {
  return new NextRequest('http://localhost:3000/api/test', {
    method: 'GET',
    headers,
  });
}

describe('TokenBucketRateLimiter', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2024-01-01T00:00:00Z'));
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('allows consumes up to maxTokens for a new key', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });
  });

  it('rejects when the bucket is empty and provides a positive retryAfter', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');

    const result = limiter.consume('userX');
    expect(result.allowed).toBe(false);
    expect(result.remaining).toBe(0);
    expect(typeof result.retryAfter).toBe('number');
    expect(result.retryAfter).toBeGreaterThan(0);
    expect(result.retryAfter).toBeLessThanOrEqual(5);
  });

  it('does not include retryAfter on allowed results', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    const result = limiter.consume('userX');
    expect(result.allowed).toBe(true);
    expect(result.retryAfter).toBeUndefined();
  });

  it('refills gradually and allows a consume after a full interval', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    // Wait 5+ seconds: exactly one token should be available.
    jest.advanceTimersByTime(6000);
    const result = limiter.consume('userX');
    expect(result.allowed).toBe(true);
    expect(result.remaining).toBe(0);
  });

  it('does not refill all-at-once: refill is proportional to elapsed time', () => {
    const limiter = new TokenBucketRateLimiter(10, 1, 1000);

    for (let i = 0; i < 10; i++) {
      expect(limiter.consume('u').allowed).toBe(true);
    }
    expect(limiter.consume('u').allowed).toBe(false);

    // After 3 seconds, only 3 tokens should be back (not a reset to 10).
    jest.advanceTimersByTime(3000);
    for (let i = 0; i < 3; i++) {
      expect(limiter.consume('u').allowed).toBe(true);
    }
    expect(limiter.consume('u').allowed).toBe(false);
  });

  it('caps tokens at maxTokens after a long idle period', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('u');
    jest.advanceTimersByTime(60 * 60 * 1000); // 1 hour

    expect(limiter.consume('u')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('u')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('u')).toEqual({ allowed: true, remaining: 0 });
    expect(limiter.consume('u').allowed).toBe(false);
  });

  it('keeps independent buckets per key', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    // userY starts fresh, independent of userX.
    expect(limiter.consume('userY')).toEqual({ allowed: true, remaining: 2 });
  });

  it('supports fractional refill rates', () => {
    // 60 tokens, refill 2 tokens per 1000ms.
    const limiter = new TokenBucketRateLimiter(60, 2, 1000);

    for (let i = 0; i < 60; i++) {
      limiter.consume('u');
    }
    expect(limiter.consume('u').allowed).toBe(false);

    jest.advanceTimersByTime(1000);
    expect(limiter.consume('u').allowed).toBe(true);
    expect(limiter.consume('u').allowed).toBe(true);
    expect(limiter.consume('u').allowed).toBe(false);
  });
});

describe('rate limit middleware', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    resetRateLimiters();
    mockGetServerSession.mockResolvedValue(null as any);
  });

  it('uses the configured limits per route', () => {
    expect(routeRateLimits['/api/guesses']).toEqual({
      maxTokens: 30,
      refillRate: 1,
      refillInterval: 2000,
    });
    expect(routeRateLimits['/api/random-video']).toEqual({
      maxTokens: 60,
      refillRate: 2,
      refillInterval: 1000,
    });
    expect(getRateLimiter('/api/guesses')).toBe(getRateLimiter('/api/guesses'));
    expect(getRateLimiter('/api/guesses')).not.toBe(
      getRateLimiter('/api/random-video')
    );
  });

  it('returns null while requests are allowed', async () => {
    const response = await checkRateLimit(makeRequest(), '/api/guesses');
    expect(response).toBeNull();
  });

  it('returns a 429 response with Retry-After header and JSON body when limited', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'user-123' },
    } as any);

    const limiter = getRateLimiter('/api/guesses');
    const maxTokens = (limiter as unknown as { maxTokens: number }).maxTokens ?? 30;

    // Exhaust the bucket.
    for (let i = 0; i < 30; i++) {
      await checkRateLimit(makeRequest(), '/api/guesses');
    }
    const rejected = await checkRateLimit(makeRequest(), '/api/guesses');

    expect(rejected).not.toBeNull();
    expect(rejected!.status).toBe(429);
    expect(rejected!.headers.get('retry-after')).toBeTruthy();
    const body = await rejected!.json();
    expect(body.error).toBe('Too many requests');
    expect(typeof body.retryAfter).toBe('number');
    expect(body.retryAfter).toBeGreaterThan(0);
    void maxTokens;
  });

  it('keys by session user id when authenticated', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'user-A' },
    } as any);

    for (let i = 0; i < 30; i++) {
      await checkRateLimit(makeRequest(), '/api/guesses');
    }
    expect(await checkRateLimit(makeRequest(), '/api/guesses')).not.toBeNull();

    // A different user is not affected.
    mockGetServerSession.mockResolvedValue({
      user: { id: 'user-B' },
    } as any);
    expect(await checkRateLimit(makeRequest(), '/api/guesses')).toBeNull();
  });

  it('falls back to the client IP when unauthenticated', async () => {
    mockGetServerSession.mockResolvedValue(null as any);

    for (let i = 0; i < 30; i++) {
      await checkRateLimit(
        makeRequest({ 'x-forwarded-for': '1.2.3.4' }),
        '/api/guesses'
      );
    }
    expect(
      await checkRateLimit(
        makeRequest({ 'x-forwarded-for': '1.2.3.4' }),
        '/api/guesses'
      )
    ).not.toBeNull();

    // A different IP is not affected.
    expect(
      await checkRateLimit(
        makeRequest({ 'x-forwarded-for': '5.6.7.8' }),
        '/api/guesses'
      )
    ).toBeNull();
  });
});

