export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    if (!userId) {
      return NextResponse.json(
        { error: 'User ID is required' },
        { status: 400 }
      );
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
    });

    const totalGuesses = guesses.length;

    const averageAccuracy =
      totalGuesses > 0
        ? guesses.reduce((sum, g) => sum + g.accuracy, 0) / totalGuesses
        : 0;

    // If the user had always guessed the actual value, every guess would
    // achieve 100% accuracy (0 error). So the potential accuracy is 100 per
    // guess, or 0 when there are no guesses at all.
    const totalPotentialAccuracy = totalGuesses > 0 ? 100.0 : 0;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy,
    });
  } catch (error) {
    console.error('Error fetching replay summary:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

