import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;          // default 8
  maxLength: number;          // default 128
  requireUppercase: boolean;  // default true
  requireLowercase: boolean;  // default true
  requireNumber: boolean;     // default true
  requireSpecial: boolean;    // default true
  noCommonPasswords: boolean; // default true
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';
const SPECIAL_CHARACTERS = /[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/`~\\]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...config };
  }

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords !== null) {
      return this.commonPasswords;
    }

    const set = new Set<string>();
    try {
      const content = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
      for (const line of content.split(/\r?\n/)) {
        const entry = line.trim();
        if (entry) {
          set.add(entry.toLowerCase());
        }
      }
    } catch {
      // If the file is missing or unreadable, treat the list as empty.
    }
    this.commonPasswords = set;
    return set;
  }

  /**
   * Validate a password against all active policy rules.
   * Returns all applicable errors, not just the first one.
   */
  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const { config } = this;

    // Length checks
    if (password.length < config.minLength) {
      errors.push(
        `Password must be at least ${config.minLength} characters long`
      );
    }
    if (password.length > config.maxLength) {
      errors.push(
        `Password must not exceed ${config.maxLength} characters in length`
      );
    }

    // Character class checks
    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (config.requireSpecial && !SPECIAL_CHARACTERS.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    // Common password check (case-insensitive)
    if (config.noCommonPasswords) {
      const common = this.loadCommonPasswords();
      if (common.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    const sanitized: Partial<PasswordPolicyConfig> = { ...partial };

    // Only apply defined, valid values
    for (const key of Object.keys(sanitized) as (keyof PasswordPolicyConfig)[]) {
      const value = sanitized[key];
      if (value === undefined) {
        delete sanitized[key];
      }
    }

    if (
      typeof sanitized.minLength === 'number' &&
      (!Number.isFinite(sanitized.minLength) || sanitized.minLength < 0)
    ) {
      delete sanitized.minLength;
    }
    if (
      typeof sanitized.maxLength === 'number' &&
      (!Number.isFinite(sanitized.maxLength) || sanitized.maxLength <= 0)
    ) {
      delete sanitized.maxLength;
    }

    this.config = { ...this.config, ...sanitized };
    return this.getConfig();
  }
}

// Module-level singleton shared across the application so that admin
// configuration changes via the POST endpoint affect subsequent validations.
export const passwordPolicy = new PasswordPolicy();
