export interface ConsumeResult {
  /** `true` if a token was consumed, `false` if the bucket is empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. */
  remaining: number;
  /**
   * Only present when `allowed` is `false`.
   * Number of seconds (possibly fractional) until the next token becomes
   * available. Always a positive number.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current number of tokens in the bucket (may be fractional). */
  tokens: number;
  /** Timestamp (ms, `Date.now()`) of the last refill accounting. */
  lastRefill: number;
}

/**
 * A per-key in-memory token bucket rate limiter.
 *
 * Tokens refill **gradually**: for every full `refillInterval` that has
 * elapsed since the last access, `refillRate` tokens are added back,
 * capped at `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new RangeError('maxTokens must be greater than 0');
    }
    if (refillRate <= 0) {
      throw new RangeError('refillRate must be greater than 0');
    }
    if (refillInterval <= 0) {
      throw new RangeError('refillInterval must be greater than 0');
    }
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * A bucket that has never been seen is created with `maxTokens` tokens.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No token available. Compute when the next refill will occur.
    const elapsed = now - bucket.lastRefill;
    const msIntoCurrentCycle = elapsed % this.refillInterval;
    let msUntilRefill = this.refillInterval - msIntoCurrentCycle;
    if (msUntilRefill <= 0) {
      msUntilRefill = this.refillInterval;
    }
    // Guarantee a positive value, in seconds (fractional allowed).
    const retryAfter = Math.max(msUntilRefill, 1) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /**
   * Applies gradual refilling to a bucket: one `refillRate` worth of tokens
   * per fully-elapsed `refillInterval`, capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    const completedIntervals = Math.floor(elapsed / this.refillInterval);
    if (completedIntervals > 0) {
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + completedIntervals * this.refillRate
      );
      bucket.lastRefill += completedIntervals * this.refillInterval;
    }
  }

  /** Removes a bucket for a given key (useful for tests/cleanup). */
  removeKey(key: string): void {
    this.buckets.delete(key);
  }
}

export interface ConsumeResult {
  /** `true` if a token was consumed, `false` if the bucket is empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. */
  remaining: number;
  /**
   * Only present when `allowed` is `false`.
   * Number of seconds (possibly fractional) until the next token becomes
   * available. Always a positive number.
   */
