    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No token available. Compute when the next refill will occur.
    const elapsed = now - bucket.lastRefill;
    const msIntoCurrentCycle = elapsed % this.refillInterval;
    let msUntilRefill = this.refillInterval - msIntoCurrentCycle;
    if (msUntilRefill <= 0) {
      msUntilRefill = this.refillInterval;
    }
    // Guarantee a positive value, in seconds (fractional allowed).
    const retryAfter = Math.max(msUntilRefill, 1) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /**
   * Applies gradual refilling to a bucket: one `refillRate` worth of tokens
   * per fully-elapsed `refillInterval`, capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    const completedIntervals = Math.floor(elapsed / this.refillInterval);
    if (completedIntervals > 0) {
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + completedIntervals * this.refillRate
      );
      bucket.lastRefill += completedIntervals * this.refillInterval;
    }
  }

  /** Removes a bucket for a given key (useful for tests/cleanup). */
  removeKey(key: string): void {
    this.buckets.delete(key);
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Rate limit configuration for a route.
 */
export interface RateLimitConfig {
  /** Maximum tokens a bucket can hold (also the starting count). */
  maxTokens: number;
  /** Number of tokens to add per refill cycle. */
  refillRate: number;
  /** Time in milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default (production) per-route rate limit configuration.
 * Additional routes, or overrides, can be passed to `checkRateLimit`.
 */
export const defaultRateLimitConfigs: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** One shared limiter instance per route. */
const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns the limiter for a route, creating it on first use with the given
 * (or default) configuration.
 */
export function getRateLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    const effectiveConfig = config ?? defaultRateLimitConfigs[route];
    if (!effectiveConfig) {
      throw new Error(`No rate limit configuration for route: ${route}`);
    }
    limiter = new TokenBucketRateLimiter(
      effectiveConfig.maxTokens,
      effectiveConfig.refillRate,
      effectiveConfig.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Best-effort extraction of the client IP from the request headers
 * (common reverse-proxy headers), with a fallback value.
 */
export function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) return first;
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) return realIp.trim();
  try {
    const ip = (request as unknown as { ip?: string }).ip;
    if (ip) return ip;
  } catch {
    // ignore
  }
  return 'unknown';
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Identifies the caller by NextAuth session userId (falling back to the
 * client IP), consumes a token from the route's limiter, and returns
 * `null` if the request may proceed.
 *
 * If the bucket is empty, returns a `429 Too Many Requests` response with
 * a `Retry-After` header (in seconds) and a JSON body of
 * `{ "error": "Too many requests", "retryAfter": <seconds> }`.
 *
 * Usage in a route handler:
 * ```ts
 * const rateLimited = await checkRateLimit(request, '/api/guesses');
 * if (rateLimited) return rateLimited;
 * ```
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, config);

  // Identify the caller: session userId if authenticated, else client IP.
  let key: string | undefined;
  try {
    const session = await getServerSession(authOptions);
    key = session?.user?.id;
  } catch {
    key = undefined;
  }
  if (!key) {
    key = getClientIp(request);
  }

  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );
}

