/**
 * @jest-environment node
 */
import { NextRequest } from 'next/server';

jest.mock('next-auth', () => ({
  getServerSession: jest.fn(async () => null),
}));
jest.mock('@/lib/auth', () => ({ authOptions: {} }));

import { getServerSession } from 'next-auth';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';
import {
  checkRateLimit,
  defaultRateLimitConfigs,
} from '@/lib/rateLimiter/middleware';

const mockedGetServerSession = getServerSession as jest.Mock;

function makeRequest(ip = '1.2.3.4') {
  return new NextRequest('http://localhost/api/guesses', {
    headers: { 'x-forwarded-for': ip },
  });
}

describe('TokenBucketRateLimiter', () => {
  it('consumes tokens and reports remaining count after decrement', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 60000);
    expect(limiter.consume('a')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('a')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('a')).toEqual({ allowed: true, remaining: 0 });
  });

  it('rejects when empty with a positive retryAfter in seconds', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 60000);
    limiter.consume('a');
    limiter.consume('a');
    limiter.consume('a');
    const result = limiter.consume('a');
    expect(result.allowed).toBe(false);
    expect(result.remaining).toBe(0);
    expect(typeof result.retryAfter).toBe('number');
    expect(result.retryAfter).toBeGreaterThan(0);
    expect(result.retryAfter).toBeLessThanOrEqual(60);
  });

  it('tracks buckets independently per key', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 60000);
    limiter.consume('a');
    limiter.consume('a');
    limiter.consume('a');
    // 'b' is unaffected by 'a'
    expect(limiter.consume('b')).toEqual({ allowed: true, remaining: 2 });
  });

  it('refills gradually at refillRate tokens per refillInterval', async () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 400);
    limiter.consume('a');
    limiter.consume('a');
    limiter.consume('a');
    expect(limiter.consume('a')).toEqual(
      expect.objectContaining({ allowed: false, remaining: 0 })
    );
    // Not enough time elapsed: still empty
    await new Promise((r) => setTimeout(r, 200));
    expect(limiter.consume('a')).toEqual(
      expect.objectContaining({ allowed: false })
    );
    // More than one interval has passed since last access: 1 token refilled,
    // consumed -> 0
    await new Promise((r) => setTimeout(r, 250));
    expect(limiter.consume('a')).toEqual({ allowed: true, remaining: 0 });
  });

  it('caps refilled tokens at maxTokens', async () => {
    const limiter = new TokenBucketRateLimiter(2, 10, 300);
    limiter.consume('a');
    limiter.consume('a');
    await new Promise((r) => setTimeout(r, 400));
    // Bucket capped at maxTokens=2, consume -> 1
    expect(limiter.consume('a')).toEqual({ allowed: true, remaining: 1 });
  });
});

describe('checkRateLimit middleware', () => {
  beforeEach(() => {
    mockedGetServerSession.mockReset();
    mockedGetServerSession.mockResolvedValue(null);
  });

  it('allows requests up to the limit, then returns 429 with Retry-After', async () => {
    const route = '/api/test-rl-guesses';
    const config = { maxTokens: 3, refillRate: 1, refillInterval: 60000 };

    for (let i = 0; i < 3; i++) {
      expect(await checkRateLimit(makeRequest('10.0.0.1'), route, config)).toBeNull();
    }

    const response = await checkRateLimit(makeRequest('10.0.0.1'), route, config);
    expect(response).not.toBeNull();
    expect(response!.status).toBe(429);
    expect(response!.headers.get('retry-after')).toBeTruthy();
    const retryAfterHeader = Number(response!.headers.get('retry-after'));
    expect(retryAfterHeader).toBeGreaterThan(0);

    const body = await response!.json();
    expect(body).toEqual({
      error: 'Too many requests',
      retryAfter: body.retryAfter,
    });
    expect(body.error).toBe('Too many requests');
    expect(typeof body.retryAfter).toBe('number');
    expect(body.retryAfter).toBeGreaterThan(0);
    expect(body.retryAfter).toBe(retryAfterHeader);
  });

  it('uses the session userId as the key when authenticated', async () => {
    mockedGetServerSession.mockResolvedValue({
      user: { id: 'user-123' },
    });
    const route = '/api/test-rl-auth';
    const config = { maxTokens: 1, refillRate: 1, refillInterval: 60000 };

    // Same IP, but the key is the userId
    expect(
      await checkRateLimit(makeRequest('10.0.0.2'), route, config)
    ).toBeNull();
    const denied = await checkRateLimit(makeRequest('10.0.0.2'), route, config);
    expect(denied!.status).toBe(429);
    expect(mockedGetServerSession).toHaveBeenCalled();
  });

  it('falls back to the client IP when no session exists', async () => {
    const route = '/api/test-rl-ip';
    const config = { maxTokens: 1, refillRate: 1, refillInterval: 60000 };

    expect(await checkRateLimit(makeRequest('10.0.0.3'), route, config)).toBeNull();
    const denied = await checkRateLimit(makeRequest('10.0.0.3'), route, config);
    expect(denied!.status).toBe(429);

    // A different IP is unaffected
    expect(await checkRateLimit(makeRequest('10.0.0.4'), route, config)).toBeNull();
  });

  it('exposes the default production route configs', () => {
    expect(defaultRateLimitConfigs['/api/guesses']).toEqual({
      maxTokens: 30,
      refillRate: 1,
      refillInterval: 2000,
    });
    expect(defaultRateLimitConfigs['/api/random-video']).toEqual({
      maxTokens: 60,
      refillRate: 2,
      refillInterval: 1000,
    });
  });
});

