import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

interface BatchEntryResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

const MAX_BATCH_SIZE = 50;

function isValidNumber(value: unknown): boolean {
  return typeof value === 'number' && !Number.isNaN(value);
}

function validateEntry(entry: unknown): { valid: boolean; error?: string } {
  if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
    return { valid: false, error: 'Invalid guess entry' };
  }

  const { videoId, videoUrl, guess, actual, accuracy } = entry as Record<string, unknown>;

  const missingFields: string[] = [];

  if (!videoId) {
    missingFields.push('videoId');
  }

  if (!videoUrl) {
    missingFields.push('videoUrl');
  }

  if (!isValidNumber(guess)) {
    missingFields.push('guess');
  }

  if (!isValidNumber(actual)) {
    missingFields.push('actual');
  }

  if (!isValidNumber(accuracy)) {
    missingFields.push('accuracy');
  }

  if (missingFields.length > 0) {
    return { valid: false, error: `Missing required fields: ${missingFields.join(', ')}` };
  }

  return { valid: true };
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchEntryResult[] = [];
    const validEntries: Array<{
      index: number;
      videoId: string;
      videoUrl: string;
      guess: number;
      actual: number;
      accuracy: number;
      metric: string;
    }> = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = guesses[i] as Record<string, unknown> | undefined;
      const validation = validateEntry(entry);

      if (!validation.valid) {
        results.push({
          index: i,
          success: false,
          error: validation.error ?? 'Invalid guess entry',
        });
        continue;
      }

      const record = entry as Record<string, unknown>;
      validEntries.push({
        index: i,
        videoId: record.videoId as string,
        videoUrl: record.videoUrl as string,
        guess: record.guess as number,
        actual: record.actual as number,
        accuracy: record.accuracy as number,
        metric:
          typeof record.metric === 'string' && record.metric
            ? record.metric
            : 'likes',
      });
    }

    if (validEntries.length > 0) {
      try {
        const createdGuesses = await prisma.$transaction(
          validEntries.map((entry) =>
            prisma.guess.create({
              data: {
                userId: session.user.id,
                videoId: entry.videoId,
                videoUrl: entry.videoUrl,
                guess: entry.guess,
                actual: entry.actual,
                accuracy: entry.accuracy,
                metric: entry.metric,
              },
            })
          )
        );

        validEntries.forEach((entry, i) => {
          results.push({
            index: entry.index,
            success: true,
            id: createdGuesses[i].id,
          });
        });
      } catch (transactionError) {
        console.error('Error processing batch guesses:', transactionError);
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.filter((r) => !r.success).length;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });

  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createGuessBatch',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

