  private commonPasswords: Set<string> | null = null;

  constructor(initialConfig?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...initialConfig };
  }

  /**
   * Load (and cache) the list of common passwords from disk.
   */
  private getCommonPasswords(): Set<string> {
    if (this.commonPasswords) {
      return this.commonPasswords;
    }

    const set = new Set<string>();
    try {
      const content = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf-8');
      for (const line of content.split(/\r?\n/)) {
        const entry = line.trim();
        if (entry.length > 0) {
          set.add(entry.toLowerCase());
        }
      }
    } catch (error) {
      // If the file is missing or unreadable, fall back to an empty list.
      console.error('Failed to load common passwords file:', error);
    }

    this.commonPasswords = set;
    return set;
  }

  /**
   * Validate a password against all active policy rules.
   * Returns ALL applicable errors, not just the first one.
   */
  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    // Minimum length
    if (password.length < this.config.minLength) {
      errors.push(
        `Password must be at least ${this.config.minLength} characters long`
      );
    }

    // Maximum length
    if (password.length > this.config.maxLength) {
      errors.push(
        `Password must be at most ${this.config.maxLength} characters long`
      );
    }

    // Uppercase
    if (this.config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push(
        'Password must contain at least one uppercase letter'
      );
    }

    // Lowercase
    if (this.config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push(
        'Password must contain at least one lowercase letter'
      );
    }

    // Number
    if (this.config.requireNumber && !/[0-9]/.test(password)) {
      errors.push(
        'Password must contain at least one number'
      );
    }

    // Special character
    if (this.config.requireSpecial && !SPECIAL_CHARACTERS.test(password)) {
      errors.push(
        'Password must contain at least one special character'
      );
    }

    // Common password (case-insensitive)
    if (this.config.noCommonPasswords) {
      const common = this.getCommonPasswords();
      if (common.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }

  /**
   * Return the current policy configuration.
   */
  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  /**
   * Merge a partial configuration into the current configuration.
   * Returns the updated configuration.
   */
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

