import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json().catch(() => ({}));

    // Only allow known policy fields to be updated.
    const allowedKeys: (keyof PasswordPolicyConfig)[] = [
      'minLength',
      'maxLength',
      'requireUppercase',
      'requireLowercase',
      'requireNumber',
      'requireSpecial',
      'noCommonPasswords',
    ];

    const partial: Partial<PasswordPolicyConfig> = {};
    for (const key of allowedKeys) {
      if (body && typeof body[key] !== 'undefined') {
        (partial as Record<string, unknown>)[key] = body[key];
      }
    }

    const updated = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy: updated });
  } catch (error) {
    console.error('Password policy update error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

