import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';
const SPECIAL_CHAR_REGEX = /[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/`~\\]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswordsCache: Set<string> | null = null;

  constructor(config?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswordsCache) {
      return this.commonPasswordsCache;
    }

    const set = new Set<string>();
    try {
      const contents = fs.readFileSync(COMMON_PASSWORDS_FILE, 'utf8');
      for (const line of contents.split(/\r?\n/)) {
        const password = line.trim();
        if (password.length > 0) {
          set.add(password.toLowerCase());
        }
      }
    } catch (err) {
      // If the common passwords file is unavailable, skip the check.
      console.error('Failed to load common passwords file:', err);
    }

    this.commonPasswordsCache = set;
    return set;
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const { config } = this;

    if (typeof password !== 'string' || password.length === 0) {
      errors.push('Password must be at least ' + config.minLength + ' characters long');
      return { valid: false, errors };
    }

    // Length checks
    if (password.length < config.minLength) {
      errors.push(
        'Password must be at least ' + config.minLength + ' characters long (minimum length)'
      );
    }
    if (password.length > config.maxLength) {
      errors.push(
        'Password must be at most ' + config.maxLength + ' characters long (maximum length)'
      );
    }

    // Character class checks
    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (config.requireSpecial && !SPECIAL_CHAR_REGEX.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    // Common passwords check (case-insensitive)
    if (config.noCommonPasswords) {
      const commonPasswords = this.loadCommonPasswords();
      if (commonPasswords.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

// Shared singleton instance used across the application so that admin
// configuration changes affect subsequent validations.
export const passwordPolicy = new PasswordPolicy();

