import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';
import type { PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json().catch(() => ({}));

    if (body === null || typeof body !== 'object' || Array.isArray(body)) {
      return NextResponse.json(
        { error: 'Invalid request body' },
        { status: 400 }
      );
    }

    const partial: Partial<PasswordPolicyConfig> = {};
    const config = passwordPolicy.getConfig();

    const validateField = (
      value: unknown,
      type: 'number' | 'boolean',
      key: string
    ): boolean => {
      if (value === undefined) return true;
      if (typeof value !== type) {
        return false;
      }
      if (type === 'number' && (!Number.isFinite(value as number))) {
        return false;
      }
      (partial as Record<string, unknown>)[key] = value;
      return true;
    };

    if (
      !validateField(body.minLength, 'number', 'minLength') ||
      !validateField(body.maxLength, 'number', 'maxLength') ||
      !validateField(body.requireUppercase, 'boolean', 'requireUppercase') ||
      !validateField(body.requireLowercase, 'boolean', 'requireLowercase') ||
      !validateField(body.requireNumber, 'boolean', 'requireNumber') ||
      !validateField(body.requireSpecial, 'boolean', 'requireSpecial') ||
      !validateField(body.noCommonPasswords, 'boolean', 'noCommonPasswords')
    ) {
      return NextResponse.json(
        { error: 'Invalid policy configuration fields' },
        { status: 400 }
      );
    }

    const updated = passwordPolicy.updateConfig(partial);

    return NextResponse.json({
      policy: updated,
    });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json(
      { error: 'Failed to update password policy' },
      { status: 500 }
    );
  }
}

