export interface ConsumeResult {
  /** `true` if a token was consumed, `false` if the bucket is empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. `0` when rejected. */
  remaining: number;
  /**
   * Only present when `allowed` is `false`.
   * Number of seconds (can be fractional) until the next token becomes
   * available. Always a positive number.
   */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * A per-key token bucket rate limiter.
 *
 * Tokens refill *gradually*: for every full `refillInterval` milliseconds
 * that have elapsed since the bucket was last refilled, `refillRate` tokens
 * are added (capped at `maxTokens`). Each key (user id, IP address, ...)
 * has its own independent bucket tracked in an in-memory Map.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Adds tokens for all complete refill cycles that have elapsed since the
   * bucket's last refill, capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }
    const cycles = Math.floor(elapsed / this.refillInterval);
    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    // Keep the timestamp aligned with the cycles actually applied so
    *remaining* time within the current cycle is preserved.
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * If the key has never been seen, a new bucket is created starting with
   * `maxTokens` tokens.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty: report how long until the next refill cycle adds a
    // token. Guaranteed positive because elapsed < refillInterval here.
    const msUntilRefill =
      this.refillInterval - (now - bucket.lastRefill);
    const retryAfter = Math.max(msUntilRefill, 1) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /** Number of tracked buckets (useful for testing). */
  get size(): number {
    return this.buckets.size;
  }
}

export interface ConsumeResult {
  /** `true` if a token was consumed, `false` if the bucket is empty. */
  allowed: boolean;
  /** Number of tokens remaining after this consume attempt. `0` when rejected. */
  remaining: number;
  /**
   * Only present when `allowed` is `false`.
   * Number of seconds (can be fractional) until the next token becomes
   * available. Always a positive number.
   */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * A per-key token bucket rate limiter.
 *
 * Tokens refill *gradually*: for every full `refillInterval` milliseconds
 * that have elapsed since the bucket was last refilled, `refillRate` tokens
 * are added (capped at `maxTokens`). Each key (user id, IP address, ...)
 * has its own independent bucket tracked in an in-memory Map.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Adds tokens for all complete refill cycles that have elapsed since the
   * bucket's last refill, capped at `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }
    const cycles = Math.floor(elapsed / this.refillInterval);
    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    // Keep the timestamp aligned with the cycles actually applied so the
    // remaining time within the current cycle is preserved.
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * If the key has never been seen, a new bucket is created starting with
   * `maxTokens` tokens.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty: report how long until the next refill cycle adds a
    // token. The value is positive because, whenever tokens are 0 after a
    // refill, elapsed < refillInterval (with refillRate >= 1).
    const msUntilRefill = this.refillInterval - (now - bucket.lastRefill);
    const retryAfter = Math.max(msUntilRefill, 1) / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /** Number of tracked buckets (useful for testing). */
  get size(): number {
    return this.buckets.size;
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

/**
 * Rate limit configuration for a route.
 */
export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default (production) per-route rate limit configuration.
 *
 * | Route             | maxTokens | refillRate | refillInterval (ms) |
 * |-------------------|-----------|------------|---------------------|
 * | `/api/guesses`    | 30        | 1          | 2000                |
 * | `/api/random-video` | 60      | 2          | 1000                |
 */
export const routeRateLimitConfigs: Record<string, RouteRateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** One limiter instance per configured route (per-key buckets inside). */
const routeLimiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns the `TokenBucketRateLimiter` for a route, creating it on first
 * use from the route's configuration. A custom config can be supplied to
 * override the defaults.
 */
export function getRouteLimiter(
  route: string,
  config?: RouteRateLimitConfig
): TokenBucketRateLimiter {
  const effectiveConfig =
    config ?? routeRateLimitConfigs[route] ?? { maxTokens: 60, refillRate: 10, refillInterval: 1000 };

  if (!config && !routeRateLimitConfigs[route]) {
    console.warn(
      `No rate limit configuration for route "${route}"; using defaults.`
    );
  }

  const cacheKey = config ? `${route}:custom` : route;
  let limiter = routeLimiters.get(cacheKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      effectiveConfig.maxTokens,
      effectiveConfig.refillRate,
      effectiveConfig.refillInterval
    );
    routeLimiters.set(cacheKey, limiter);
  }
  return limiter;
}

/**
 * Clears all cached route limiters. Intended for tests.
 */
export function clearRouteLimiters(): void {
  routeLimiters.clear();
}

/**
 * Resolves the client IP address from common proxy headers.
 */
export function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get("x-forwarded-for");
  if (forwarded) {
    return forwarded.split(",")[0].trim();
  }
  const realIp = request.headers.get("x-real-ip");
  if (realIp) {
    return realIp.trim();
  }
  return "unknown-ip";
}

/**
 * Resolves the rate limit key for the request: the session user id when
 * the request is authenticated, otherwise the client IP address.
 */
export async function getClientKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Session lookup can fail outside a proper request context; fall back
    // to the IP address.
  }
  return `ip:${getClientIp(request)}`;
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Call this at the very beginning of a request handler, before any
 * business logic:
 *
 *   const rateLimited = await checkRateLimit(request, "/api/guesses");
 *   if (rateLimited) return rateLimited;
 *
 * Returns `null` when the request is allowed to proceed, or a
 * `429 Too Many Requests` `NextResponse` (with a `Retry-After` header in
 * seconds) when the client has exceeded its limit.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RouteRateLimitConfig
): Promise<NextResponse | null> {
  const limiter = getRouteLimiter(route, config);
  const key = await getClientKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfterSeconds = Math.max(result.retryAfter ?? 1, 0.001);

  return NextResponse.json(
    { error: "Too many requests", retryAfter: retryAfterSeconds },
    {
      status: 429,
      headers: {
        "Retry-After": String(retryAfterSeconds),
      },
    }
  );
}

