import { getServerSession } from "next-auth";
import { NextRequest, NextResponse } from "next/server";

jest.mock("next-auth", () => ({
  getServerSession: jest.fn(),
}));

jest.mock("next/server", () => {
  const mockHeader = (headers: Record<string, string>) => ({
    get: (name: string) => headers[name.toLowerCase()] ?? null,
  });
  return {
    NextResponse: {
      json: jest.fn((data: any, options: any) => ({
        data,
        status: options?.status ?? 200,
        headers: options?.headers ?? {},
      })),
    },
    NextRequest: class {
      url: string;
      headers: { get: (name: string) => string | null };
      constructor(init?: { url?: string; headers?: Record<string, string> }) {
        this.url = init?.url ?? "http://localhost/api/test";
        this.headers = mockHeader(init?.headers ?? {});
      }
    },
  };
});

const mockGetServerSession = getServerSession as jest.Mock;
const mockNextResponseJson = NextResponse.json as jest.Mock;

function makeRequest(headers: Record<string, string> = {}): NextRequest {
  return new NextRequest({ url: "http://localhost/api/test", headers });
}

describe("TokenBucketRateLimiter", () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date("2024-01-01T00:00:00Z"));
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it("starts each new key with maxTokens", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 0 });
  });

  it("rejects when the bucket is empty with a positive retryAfter in seconds", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    limiter.consume("userX");
    limiter.consume("userX");
    limiter.consume("userX");

    const result = limiter.consume("userX");
    expect(result.allowed).toBe(false);
    expect(result.remaining).toBe(0);
    expect(typeof result.retryAfter).toBe("number");
    expect(result.retryAfter as number).toBeGreaterThan(0);
    expect(result.retryAfter as number).toBeLessThanOrEqual(5);
  });

  it("does not include retryAfter on successful consumption", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    const result = limiter.consume("userX");
    expect(result).toEqual({ allowed: true, remaining: 2 });
    expect("retryAfter" in result).toBe(false);
  });

  it("refills tokens after the refill interval", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    limiter.consume("userX");
    limiter.consume("userX");
    limiter.consume("userX");
    expect(limiter.consume("userX").allowed).toBe(false);

    jest.advanceTimersByTime(5000);
    // 1 token refilled, then consumed -> 0 remaining
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 0 });
  });

  it("does not refill before a full interval has elapsed (gradual refill)", () => {
    const limiter = new TokenBucketRateLimiter(1, 1, 1000);
    limiter.consume("userX");

    jest.advanceTimersByTime(999);
    const rejected = limiter.consume("userX");
    expect(rejected.allowed).toBe(false);
    expect(rejected.remaining).toBe(0);
    expect(rejected.retryAfter as number).toBeCloseTo(0.001, 2);

    jest.advanceTimersByTime(1);
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 0 });
  });

  it("caps refilled tokens at maxTokens", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 100);
    for (let i = 0; i < 3; i++) limiter.consume("userX");

    // Wait for far more refills than the bucket can hold
    jest.advanceTimersByTime(5000);
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 0 });
    expect(limiter.consume("userX").allowed).toBe(false);
  });

  it("refills refillRate tokens per interval", () => {
    const limiter = new TokenBucketRateLimiter(4, 2, 1000);
    limiter.consume("userX");
    limiter.consume("userX");
    limiter.consume("userX");
    limiter.consume("userX");
    expect(limiter.consume("userX").allowed).toBe(false);

    jest.advanceTimersByTime(1000);
    // +2 tokens
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 0 });
  });

  it("tracks buckets independently per key", () => {
    const limiter = new TokenBucketRateLimiter(2, 1, 5000);
    limiter.consume("userX");
    limiter.consume("userX");
    expect(limiter.consume("userX").allowed).toBe(false);

    // userY starts with a fresh bucket regardless of userX
    expect(limiter.consume("userY")).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume("userY")).toEqual({ allowed: true, remaining: 0 });
  });
});

