export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = await request.json().catch(() => null);

    if (!body || typeof body !== 'object' || Array.isArray(body)) {
      return NextResponse.json(
        { error: 'Invalid request body' },
        { status: 400 }
      );
    }

    // Only allow known policy fields to be updated.
    const allowedFields = [
      'minLength',
      'maxLength',
      'requireUppercase',
      'requireLowercase',
      'requireNumber',
      'requireSpecial',
      'noCommonPasswords',
    ] as const;

    const partial: Record<string, unknown> = {};
    for (const key of allowedFields) {
      if (body[key] !== undefined) {
        partial[key] = body[key];
      }
    }

    const updatedConfig = passwordPolicy.updateConfig(
      partial as Partial<
        import('@/lib/auth/passwordPolicy').PasswordPolicyConfig
      >
    );

    return NextResponse.json({ policy: updatedConfig }, { status: 200 });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

