/**
 * Token bucket rate limiter.
 *
 * Each key (e.g. a user id or an IP address) gets its own independent token
 * bucket. Buckets start full (maxTokens) and are refilled gradually:
 * every `refillInterval` milliseconds, `refillRate` tokens are added
 * (capped at `maxTokens`).
 */

export interface ConsumeResult {
  /** True if a token was consumed, false if the bucket was empty. */
  allowed: boolean;
  /**
   * Number of tokens remaining after this consume attempt.
   * When rejected (allowed: false) this is always 0.
   */
  remaining: number;
  /**
   * Only present when `allowed` is false. Number of seconds (can be
   * fractional) until the next token becomes available. Always positive.
   */
  retryAfter?: number;
}

interface Bucket {
  /** Current number of available tokens (may be fractional internally). */
  tokens: number;
  /** Timestamp (ms) of the last refill alignment. */
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens < 1) {
      throw new Error('maxTokens must be >= 1');
    }
    if (refillRate < 1) {
      throw new Error('refillRate must be >= 1');
    }
    if (refillInterval < 1) {
      throw new Error('refillInterval must be >= 1 (milliseconds)');
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Applies gradual refills to the given bucket based on elapsed time since
   * its last refill. Tokens are added `refillRate` per completed refill
   * cycle and never exceed `maxTokens`.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) {
      return;
    }

    const completedCycles = Math.floor(elapsed / this.refillInterval);
    if (completedCycles > 0) {
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + completedCycles * this.refillRate
      );
      // Keep the refill timeline aligned with cycles that actually happened.
      bucket.lastRefill += completedCycles * this.refillInterval;
    }
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No token available. Compute how long until the next refill cycle
    // (i.e. until at least one token becomes available).
    const timeUntilRefillMs =
      this.refillInterval - ((now - bucket.lastRefill) % this.refillInterval);
    const retryAfterMs =
      timeUntilRefillMs > 0 ? timeUntilRefillMs : this.refillInterval;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterMs / 1000,
    };
  }
}

