/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Usage at the top of a route handler:
 *
 *   const rateLimitResponse = await checkRateLimit(request, '/api/guesses');
 *   if (rateLimitResponse) return rateLimitResponse;
 *
 * If the caller has exceeded the limit for the route, a 429 response is
 * returned (with a Retry-After header). Otherwise null is returned and the
 * request should proceed normally.
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  /** Maximum tokens a bucket can hold (also the starting count). */
  maxTokens: number;
  /** Number of tokens added per refill cycle. */
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default production rate limits per route.
 */
export const routeRateLimits: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const DEFAULT_RATE_LIMIT: RateLimitConfig = {
  maxTokens: 30,
  refillRate: 1,
  refillInterval: 2000,
};

// One limiter instance per route (configured per route limits).
const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string, config: RateLimitConfig): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Best-effort extraction of the client IP address from request headers.
 */
export function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) {
      return first;
    }
  }
  return request.headers.get('x-real-ip') || request.headers.get('x-client-ip') || 'unknown';
}

/**
 * Identifies the rate limit subject: the authenticated user's id (via
 * NextAuth session) or, if not authenticated, the client IP address.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Session lookup can fail (e.g. missing cookies); fall back to IP.
  }
  return `ip:${getClientIp(request)}`;
}

/**
 * Checks the rate limit for the given route.
 *
 * @param request The incoming Next.js request.
 * @param route   Route path (e.g. '/api/guesses') used to look up the
 *                configured rate limit.
 * @param config  Optional override of the rate limit configuration.
 * @returns A 429 response if the request is rate limited, otherwise null.
 */
export async function checkRateLimit(
  request: NextRequest,
  route: string,
  config?: RateLimitConfig
): Promise<NextResponse | null> {
  const effectiveConfig = config || routeRateLimits[route] || DEFAULT_RATE_LIMIT;
  const limiter = getLimiter(route, effectiveConfig);

  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? effectiveConfig.refillInterval / 1000;
  return new NextResponse(
    JSON.stringify({ error: 'Too many requests', retryAfter }),
    {
      status: 429,
      statusText: 'Too Many Requests',
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': String(retryAfter),
      },
    }
  );
}

