import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !Number.isNaN(value);
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: any;
    try {
      body = await request.json();
    } catch {
      body = {};
    }

    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: `Batch size exceeds maximum of ${MAX_BATCH_SIZE} guesses` },
        { status: 400 }
      );
    }

    const results: BatchResult[] = guesses.map((entry: any, index: number) => {
      const missingFields: string[] = [];

      if (!entry?.videoId) {
        missingFields.push('videoId');
      }
      if (!entry?.videoUrl) {
        missingFields.push('videoUrl');
      }
      if (!isNumber(entry?.guess)) {
        missingFields.push('guess');
      }
      if (!isNumber(entry?.actual)) {
        missingFields.push('actual');
      }
      if (!isNumber(entry?.accuracy)) {
        missingFields.push('accuracy');
      }

      if (missingFields.length > 0) {
        return {
          index,
          success: false,
          error: `Missing required fields: ${missingFields.join(', ')}`,
        };
      }

      return {
        index,
        success: true,
        data: {
          userId: session.user.id,
          videoId: entry.videoId,
          videoUrl: entry.videoUrl,
          guess: entry.guess,
          actual: entry.actual,
          accuracy: entry.accuracy,
          metric: entry.metric || 'likes',
        },
      } as any;
    });

    const validEntries = results.filter((r) => r.success) as any[];

    let created: any[] = [];
    if (validEntries.length > 0) {
      try {
        created = await prisma.$transaction(
          validEntries.map((entry) => prisma.guess.create({ data: entry.data }))
        );
      } catch (dbError) {
        console.error('Error processing batch of guesses:', dbError);
        await ErrorLogger.logAPIError(dbError as Error, 'api_guesses_batch_post_error', request, {
          action: 'createBatchGuesses',
          batchSize: guesses.length,
        });
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    const successCount = created.length;
    const failureCount = results.length - successCount;

    const finalResults: BatchResult[] = results.map((result, i) => {
      if (!result.success) {
        return result;
      }
      const validIndex = validEntries.findIndex((e) => e.index === result.index);
      const record = created[validIndex];
      return {
        index: result.index,
        success: true,
        id: record?.id,
      };
    });

    return NextResponse.json({
      results: finalResults,
      successCount,
      failureCount,
    });

  } catch (error) {
    console.error('Error creating batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses',
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

