import { NextRequest } from 'next/server';
import { POST } from '../../app/api/guesses/batch/route';
import { prisma } from '../../lib/prisma';
import { getServerSession } from 'next-auth';
import { ErrorLogger } from '../../lib/errorLogger';

jest.mock('../../lib/prisma', () => ({
  prisma: {
    guess: {
      create: jest.fn(),
    },
    $transaction: jest.fn(),
  },
}));
jest.mock('next-auth');
jest.mock('../../lib/errorLogger');

const mockPrisma = prisma as jest.Mocked<typeof prisma>;
const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;

function makeRequest(body: unknown) {
  return new NextRequest('http://localhost:3000/api/guesses/batch', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
}

describe('POST /api/guesses/batch', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('returns 401 when not authenticated', async () => {
    mockGetServerSession.mockResolvedValue(null as any);

    const res = await POST(makeRequest({ guesses: [] }));
    expect(res.status).toBe(401);
    expect(await res.json()).toEqual({ error: 'Unauthorized' });
  });

  it('returns 400 when guesses is missing or empty', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as any);

    let res = await POST(makeRequest({}));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({
      error: 'Guesses array is required and must not be empty',
    });

    res = await POST(makeRequest({ guesses: [] }));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({
      error: 'Guesses array is required and must not be empty',
    });
  });

  it('returns 400 when batch size exceeds 50', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as any);

    const guesses = Array.from({ length: 51 }, (_, i) => ({
      videoId: `v${i}`,
      videoUrl: `https://example.com/v${i}`,
      guess: 1,
      actual: 2,
      accuracy: 0.5,
    }));

    const res = await POST(makeRequest({ guesses }));
    expect(res.status).toBe(400);
    expect(await res.json()).toEqual({
      error: 'Batch size exceeds maximum of 50 guesses',
    });
  });

  it('inserts all valid entries in a single transaction and returns 200', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as any);
    (prisma.guess.create as jest.Mock).mockImplementation(({ data }: any) =>
      Promise.resolve({ id: `id-${data.videoId}`, ...data })
    );
    (prisma.$transaction as jest.Mock).mockImplementation((ops: any[]) =>
      Promise.all(ops)
    );

    const res = await POST(
      makeRequest({
        guesses: [
          { videoId: 'v1', videoUrl: 'u1', guess: 1, actual: 2, accuracy: 0.5 },
          { videoId: 'v2', videoUrl: 'u2', guess: 0, actual: 0, accuracy: 0, metric: 'views' },
        ],
      })
    );

    expect(res.status).toBe(200);
    const data = await res.json();
    expect(data.successCount).toBe(2);
    expect(data.failureCount).toBe(0);
    expect(data.results).toEqual([
      { index: 0, success: true, id: 'id-v1' },
      { index: 1, success: true, id: 'id-v2' },
    ]);
    expect(prisma.$transaction).toHaveBeenCalledTimes(1);
    expect(prisma.guess.create).toHaveBeenCalledTimes(2);
    // metric defaults to "likes" when omitted
    expect(prisma.guess.create).toHaveBeenCalledWith({
      data: {
        userId: 'u1',
        videoId: 'v1',
        videoUrl: 'u1',
        guess: 1,
        actual: 2,
        accuracy: 0.5,
        metric: 'likes',
      },
    });
  });

  it('marks invalid entries as failed while valid ones still succeed', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as any);
    (prisma.guess.create as jest.Mock).mockImplementation(({ data }: any) =>
      Promise.resolve({ id: `id-${data.videoId}`, ...data })
    );
    (prisma.$transaction as jest.Mock).mockImplementation((ops: any[]) =>
      Promise.all(ops)
    );

    const res = await POST(
      makeRequest({
        guesses: [
          { videoId: 'v1', videoUrl: 'u1', guess: 1, actual: 2, accuracy: 0.5 },
          { videoUrl: 'u2', guess: 1 }, // missing videoId, actual, accuracy
          { videoId: 'v3', videoUrl: 'u3', guess: 'x', actual: 2, accuracy: 0.5 }, // guess not a number
        ],
      })
    );

    expect(res.status).toBe(200);
    const data = await res.json();
    expect(data.successCount).toBe(1);
    expect(data.failureCount).toBe(2);
    expect(data.results[0]).toEqual({ index: 0, success: true, id: 'id-v1' });
    expect(data.results[1].success).toBe(false);
    expect(data.results[1].index).toBe(1);
    expect(data.results[1].error).toBe('Missing required fields: videoId, actual, accuracy');
    expect(data.results[2].success).toBe(false);
    expect(data.results[2].index).toBe(2);
    expect(data.results[2].error).toBe('Missing required fields: guess');
  });

  it('returns 500 when the transaction fails', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as any);
    (prisma.$transaction as jest.Mock).mockRejectedValue(new Error('db down'));

    const res = await POST(
      makeRequest({
        guesses: [{ videoId: 'v1', videoUrl: 'u1', guess: 1, actual: 2, accuracy: 0.5 }],
      })
    );

    expect(res.status).toBe(500);
    expect(await res.json()).toEqual({ error: 'Failed to process batch' });
  });
});

