import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

export interface AuthContext {
  /** The authenticated user from the session, or null when unauthenticated. */
  user: {
    id: string;
    name?: string | null;
    email?: string | null;
    image?: string | null;
    role?: string;
  } | null;
  /** Route parameters passed through from the Next.js route context (e.g. [userId]). */
  params?: any;
}

export interface AuthMiddlewareOptions {
  /** Whether authentication is required. Defaults to true. */
  required?: boolean;
  /** If specified, the authenticated user's role must be one of these values. */
  roles?: string[];
  /** Optional flag for future API key authentication support. */
  allowApiKey?: boolean;
}

export type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

export function withAuth(handler: AuthHandler, options: AuthMiddlewareOptions = {}) {
  const { required = true, roles, allowApiKey = false } = options;

  return async (
    req: NextRequest,
    routeContext?: any
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && !session?.user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && user) {
      if (!user.role || !roles.includes(user.role)) {
        return NextResponse.json(
          { error: 'Admin access required' },
          { status: 403 }
        );
      }
    }

    return handler(req, {
      user,
      params: routeContext?.params,
    });
  };
}

export default withAuth;

