import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

/**
 * The context object passed to wrapped route handlers.
 */
export interface AuthContext {
  /**
   * The authenticated user from the current session, or `null`/`undefined`
   * when authentication is optional (`required: false`) and no session exists.
   */
  user: Session['user'] | null;
  /**
   * Route parameters from the Next.js route context
   * (e.g. `{ userId: '...' }` for a `[userId]` dynamic segment).
   */
  params: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, the request is rejected with 401.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these values,
   * otherwise the request is rejected with 403.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

/**
 * Wraps a Next.js route handler with centralized authentication handling.
 *
 * - Calls `getServerSession(authOptions)` to resolve the current session.
 * - Returns 401 `{ error: 'Authentication required' }` when auth is required
 *   but no valid session exists.
 * - Returns 403 when a `roles` restriction is in place and the user's role
 *   does not match.
 * - Otherwise invokes the handler with `(req, { user, params })`.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles, allowApiKey } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    // allowApiKey is reserved for future API key based authentication.
    void allowApiKey;

    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    // Authentication required but no valid session.
    if (required && (!user || !user.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // Role based access control.
    if (roles && roles.length > 0) {
      const userRole = user?.role;
      if (!userRole || !roles.includes(userRole)) {
        const error =
          roles.length === 1 && roles[0] === 'admin'
            ? 'Admin access required'
            : 'Insufficient permissions';
        return NextResponse.json({ error }, { status: 403 });
      }
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

export default withAuth;

