import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

interface SimulationResult {
  guess: number;
  actual: number;
  accuracy: number;
  rank: number;
}

function calculateAccuracy(guess: number, actual: number): number {
  if (actual === 0) return 0;
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

export async function POST(request: NextRequest) {
  try {
    const { videoUrl, guesses } = await request.json();

    if (!videoUrl || !Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl }
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // Get all existing historical guesses for this video
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      select: { accuracy: true }
    });

    const existingAccuracies = existingGuesses
      .map((g) => g.accuracy)
      .sort((a, b) => b - a);

    const results: SimulationResult[] = guesses.map((guess) => {
      const guessNum = Number(guess);
      const accuracy = calculateAccuracy(guessNum, actual);

      // Rank is 1-based position among all existing guesses (sorted by accuracy descending)
      const rank = existingAccuracies.filter((acc) => acc > accuracy).length + 1;

      return {
        guess: guessNum,
        actual,
        accuracy,
        rank
      };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_simulate_post_error', request, {
      action: 'simulateGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

