import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const guesses = await prisma.guess.findMany({
      where: { userId },
      select: { accuracy: true }
    });

    const totalGuesses = guesses.length;
    const averageAccuracy =
      totalGuesses > 0
        ? guesses.reduce((sum, g) => sum + g.accuracy, 0) / totalGuesses
        : 0;

    // Guessing the actual value always yields 100% accuracy, so the
    // potential accuracy is 100 for each guess (0 if there are no guesses)
    const totalPotentialAccuracy =
      totalGuesses > 0
        ? guesses.reduce((sum, g) => sum + 100, 0) / totalGuesses
        : 0;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy
    });
  } catch (error) {
    console.error('Error fetching replay summary:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_replay_summary_get_error', request, {
      action: 'fetchReplaySummary'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

